INSERT INTO `articles_mcswinneys` VALUES (1,666,17,'article #666','Steve Five is a... a... a?  He lives in San Francisco.  There he awaits the full revolution of Evil Alignment, divines this time using astrology techniques that only he understands.  He is a patient man.','2002-09-13 20:23:45','2002-09-13 20:23:45'),(2,3023,17,'table for one','Matt is this crazy guy who has drug problems and gets really depressed, but he also has lots of ideas and is a film maker.  You make the call.','2002-09-21 21:05:15','2002-09-21 21:04:29'),(3,3036,17,'the first time','A New Zealander, Sarah is headed for the hills.  In the mean time, she dispatches taxi cabs, and wrangles the children -- her own and others.','2002-09-21 23:32:54','2002-09-21 23:32:54'),(4,3050,17,'seoul korea.','Our correspondent in Korea, David Matte reports on the United States in International Politics.','2002-09-29 17:58:01','2002-09-29 17:58:01'),(5,3058,17,'the boogie-down bronx','May started a fight club in her neck of the Bronx recently.  She teaches, and is fed up with blah.','2002-10-08 09:36:39','2002-10-08 01:22:26'),(6,3606,17,'This bitch left no title.','Austin Swinney is perhaps actually drunk.','2004-05-20 07:27:52','2004-05-20 07:27:52');
/*!40000 ALTER TABLE `articles_mcswinneys` ENABLE KEYS */;
UNLOCK TABLES;

