\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" )\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", 1, 253, 0, 0, \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"24.42.194.13\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" )\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", 0, 460, 0, 0, \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"24.42.194.13\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" )\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", 0, 960, 0, 0, \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"24.42.194.13\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" )\\\\\\\\\\\\\\\", 0, 2612, 0, 0, \\\\\\\\\\\\\\\"24.42.194.13\\\\\\\\\\\\\\\" )\\\", 6, 8873, 0, 0, \\\"24.42.194.13\\\" )</p>'),(2518,'<P> I take an ajunct course at a local community high school in the next town over.  For some reason, our class was scheduled during the same time slot that the high school kids play basketball, making parking virtually impossible almost every week. <P>\r\n\r\n<P> I thought I was late to class, but when I got to my seat and looked around, I realized that the teacher was not there yet.  Instead, I got to hear the man sitting a few seats over tell the lady in front of him about how sick he was the week before. <P>\r\n\r\n<P> \\\"I spent the ENTIRE week sleeping and drinking water.  I finally went to the hospital.  I thought I had diabetes or something.\\\" <P>\r\n\r\n<P> Her wide-eyed stare displayed a small amount of shock, and an even smaller amount of concern.  \\\"Well, did you manage to find out what was wrong?\\\" <P>\r\n\r\n<P> \\\"Nothing. I\\\'m just lazy, I guess.\\\" <P>'),(2519,'<p>It was at Sushi Sam in San Mateo.</p>\r\n<p>The chef is too funny; yeah, maybe actually too funny; I suspect him to be a sushi salesman or something. When he\\\'s too nice with me H also suspects him to be gay. I don\\\'t think so. (It\\\'s stange how I accept to be satisfied if a girl is nicer to me because she\\\'s \\\'sexualy\\\' attracted. Why am I disappointed if a guy is nice for the same reason? I must be just a salesman)\r\n</p><p>\r\nSo anyway I love this chef. He looks perfectly like <a href=\\\"http://fernandel.online.fr/\\\">Fernandel</a>. OK, let\\\'s says he looks a bit like Fernandel, but he acts a lot like him. And that night, he started talking tourist-style french to a couple next to us. \\\"Bonsoil!\\\" (huge smile). \\\"Comment ca ba?\\\". And the lady answers him a bit, in french too, which a strong accent. \\\"Tres bien merci\\\" etc. This game lasts a few lines. The couple eats a bunch of California rolls, the straight way. I see them staring at the tiny raw squids we\\\'re having. They get their bill and stand up. Fernandel starts again his french tourist acting game. \\\"Bonsoil!\\\" I already had enough beer and sake. I start acting as well. \\\"A bientot!\\\" And that\\\'s when the wrong thing happens.\r\n</p><p>\r\nThe lady talks to me in french. Good french, this time, still with this strong accent. I answer, a bit surprised. Since the chef was only saying phrase-book sentences, I thought she couldn\\\'t say more either. And then I ask, to be nice:<br>\r\n- your french is good! Where did you learn it?<br>\r\n- actually, I am Canadian.<br>\r\nShe was still smiling, but I couldn\\\'t anymore. I stuttered a kind of explanation of my mistake. I think I have rarely been more unclear. This wasn\\\'t even french anymore.</p>'),(2520,'it was embarrassing to see you standing beneath my bedroom window. in fact, it was so trite i can barely write about it here. but there you were, grinning insanely, the moonlight competing shamelessly with your teeth. i said no when you\r\nasked if you ought to sing a song. but you didn\\\'t listen, which is understandable, you never do. i picked up the first thing that came to my hand, the glossy paper of the magazine slipping from my fingers too fast. you didn\\\'t even duck. i grabbed and threw anything -- my pillow, a book, my binder, the tissue box -- everything i could fit through the open window. you just laughed and let them fall to the ground, at your bare feet, and continued singing that stupid song. until i couldn\\\'t help but slip out myself, barely aware of the green staining my white socks, as i ran to cover your mouth with my fingers. \r\n<br><br>\r\ni remember the shock of the bite, <br> \r\nthe first drop of rain in the darkness, the<br> \r\nwind slipping into fingers in my hair,<br> \r\nthe end of your song.<br> '),(2521,'so what?'),(3892,'she came to stay. no, she really did.<br>\r\n<br> \r\ni used to keep diaries before i went to live on the internet. this is the time. and this is the record\r\nof the time. here is the work. and here is work about the work. this\r\nwork is drawing and writing and gluing and tearing and cutting and\r\nspraying and tracing and copying. this work is feeling and thinking and\r\ngesturing and parting and mending and, over time, positioning and\r\nrepositioning. what is the work here, then? is it to explain the work?\r\ncan the work be explained? what would be the point, exactly? and will\r\nit then be explained away? are you asking: elaine, why did you do\r\nthis?<br>\r\n<br>\r\n&nbsp;<img src=\\\"http://static.flickr.com/33/59021351_c9913bd512.jpg?v=0\\\"><br>\r\n<br>\r\nit\\\'s all in the how of it.<br>\r\n<br>\r\nthis is the work and this is the record of\r\nthe work. the layers, the secrets, the difficulties, the tearing, the\r\nrending, the mending, the covering up, and the re-covering. here,\r\nthen, are gestures. there are some words. there are the words and now\r\nhere are some words about the words. she came to stay and then i wrote\r\nabout her coming to stay.<br>\r\n<br>\r\nif i had never read she came to stay i\r\nmight not have felt <i>quite</i> so foolish when she came to stay and then,\r\nunlike me, she stayed up late with him, and she drank with him and she\r\nsmoked with him. she had been a friend of mine. i wonder at what point\r\ni stopped being loved by her and became a means to an end?<br>\r\n<br>\r\nof course, I\r\nwonder when he stopped loving me enough as well. i wonder when our\r\nrelationship became a representation of a relationship? i guess the\r\ndynamic of that had to have had it\\\'s own momentum. all it needed was a\r\nshove in the right direction. the irony was that the reason i read\r\nshe came to stay in the first place was because it had been a\r\nfavourite of a previous ex of his, and she was a woman whose opinion i\r\nhad reason to admire, although i never really met her. <br>\r\n<br>\r\nand then it all\r\nhappened, crashed around me, cruelly miming the gist of the tale\r\n(although there was no scene involving a head in a gas oven, and i did\r\nnot keep my man. then again, i am not simone de beauvoir). the shame\r\nof it! the shame of it!<br>\r\n<br>\r\n&nbsp;<img src=\\\"http://static.flickr.com/24/59023698_d2d6d1cb90.jpg?v=0\\\">\r\n\r\n<br>\r\n<br>\r\nand the utter utter bereavement for what I had thought was my life. i\r\nwrote a diary, kept it all in there. and now i keep a livejournal. i\r\ndoubt i censor myself much more or much less. just in a different way\r\nabout different things. things kept in tend to blurt out somehow, but\r\nthe days of the secret diary are long gone. and one day I decided that\r\nthe diaries might be better used as material for collage, so i ripped\r\nthe first few pages of the second book out, tore them up a bit and\r\ncollaged them onto a drawing. what i wasn\\\'t expecting was the pain that\r\nwent with it. that was a surprise. I had not thought of them as having\r\na visceral connection to me.<br>\r\n<br>\r\ni sectioned them up into squares once i was done with the tearing and\r\nthe gluing and the stencilling, in order to make them more opaque and\r\nabstract and formal. to shroud the immediacy of the pain in something\r\nformally parcelled. part of a process of parting. i lined them up in\r\ngroups of four along a wall, there were twelve of them in that row,\r\nlike the first few bars of some abstract version of a musical score.\r\nhere they are again now, and this time they are repositioned,\r\nregrouped, reprocessed, recontextualised. this is only natural. they\r\ncontinue to talk back to me over time as the situation fades and melts\r\ninto something called the past.<br>\r\n<br>\r\ni posted some pictures on citynoise of a bin and a bucket in the\r\nstreet. i called the piece <i><A href=\\\"http://www.citynoise.org/article/2258\\\">abject objects</a></i>. it attracted this comment\r\nfrom vz: <i> to photograph something, even something abject, is to\r\naestheticize it</i>. is this the problem? is all re-presentation\r\nnecessarily a bit camp? a bit of a joke? like the relationship itself\r\nmust have become, a representation of something located elsewhere. a\r\nbit in quotation marks? perhaps real abjection is necessarily private\r\nand lonely, and the moment the communication is made, the loneliness is\r\nover, like the comfortable misery of listening to the smiths.<br>\r\n<br>\r\n&nbsp;<img src=\\\"http://static.flickr.com/27/59021350_dbf92a4908.jpg?v=0\\\">'),(2522,'deadly little monsters</br>\r\nhovering over the</br>\r\ndark forest</br>\r\nI am not scared</br>\r\nto wait a little longer</br>\r\nto see them die\r\n<p>\r\nstand still</br>\r\nthe morning is undead\r\n<p>\r\nbeautiful, terrible</br>\r\nlight that finds a way</br>\r\ninto the sky</br>\r\nit shocks like lightning</br>\r\nbut anyway it feels</br>\r\nlike home again\r\n<p>\r\nstand still</br>\r\nthe morning is undead\r\n<p>\r\nit whispers softly</br>\r\nit whispers softly'),(2523,'i discovered something very funny and interesting to me today. i was on the streetcar this morning, in my usual first-thing-in-the-morning stuppor, staring out the window. as i generally do, i\\\'ll stare at whatever catches my attention, often outside, on the street.\r\n<p>this time i was blankly looking at the front door of a restaurant. but here\\\'s what\\\'s strange. it was just over the shoulder of the man sitting in front of me. now, you must understand, where i was sitting, at the back of the car, there\\\'s 7 seats in a \\\"U\\\" type shape. So, the man was sitting 1/2 facing towards me.\r\n<p>apparently he seemed to think i was staring at him, while he was reading his book. he looked up, noticed me staring (i barely even acknoledged his presense) and decided to relocate. At first I thought he was getting off, but no. He went and sat at the FRONT of the streetcar.\r\n<p>and the kicker to the whole, apparently uncomfortable for him, situation was the trepid look i was given while he exited the streetcar three stops later.\r\n<p>i guess i know how to get people to move away from me now. pretend i\\\'m attracted to them. hopefully this doesn\\\'t take effect on people i <b>actually</b> find attractive. no offence to the guy, but, really, just not my type.\r\n<p>it would have been interesting to find out if it really was my absent-minded staring that had prompted the relocation. regardless, it gave me more room in which to sit and stare out the window.'),(2524,'<P> \\\"HELP!\\\" <P>\r\n\r\n<P> My room is in the basment. I hear my father yell, but I ignore it.  My father and my brother wrestle all the time. Someone is always yelling for help. No one ever means it.<P>\r\n\r\n<P> \\\"HELP!\\\" <P>\r\n\r\n<P> It\\\'s the exact same tone of voice. The scream is the exact same length of time.  I turn the volume down on the TV so that I can hear clearly. <P>\r\n\r\n<P> \\\"HELP!\\\" <P>\r\n\r\n<P> I start to open the door and make my way through the basement.  I hear falling water and look up at the cieling of the small half-bathroom near the stairs.  Water is leaking through the drop cieling. <P>\r\n\r\n<P> \\\"HELP! HELP! HELP! How many times does a person have to yell for HELP! in this house?\\\" <P>\r\n\r\n<P> Quite a few, I\\\'d say; especially when you generally nasty most of the time. <P>\r\n\r\n<P> My brother and I make it into the kitchen at the same time. My dad is yelling for pots, but his large body is blocking the cabinet where the pots are kept.  He is leaning IN the same cabinet, because they are stored under the sink with the pipes. <P>\r\n\r\n<P> It is not my brother\\\'s fault that the garbage disposal broke when he tried to get rid of the 2 day old food that was still on the counter.  It is not my brother\\\'s fault that this caused the sink to clog.  It is not our fault that the ENTIRE bottle of drain-o type liquid did not HELP the clog.  <P>\r\n\r\n<P> Apparently, it IS our fault that my father felt compelled to somehow open up one of these pipes knowing that the sink was filled with toxic drain cleaner. <P>\r\n\r\n<P> The entire house reaks of drain cleaner.  This is my fault. Don\\\'t forget that. <P>\r\n'),(2525,'<!-- if i had wanted it in upper case, i would have put it in upper case. -->\r\n<p>\r\nthe most beautiful sunrise i have ever seen in my life was recently, in australia. we had been driving all night across new south wales, through arid bush country. \r\n</p><p>\r\n<pre><tt>\r\n*weeb* bok bok my o\r\n*weeb* i am too sleepy to get off the couch\r\n*o* hello weeb\r\n*o* who wants to see lovely sunrise in .au?\r\n*o* oh weebie\r\n*o* you are so cute\r\n*weeb* peww\r\n*weeb* i am sneepsy\r\n*weeb* tell me about sunrises\r\n*o* <a href=\"http://saturn5.com/olivia/images/places/australia2001/near_tocumwal/\">i can show you the photos</a>\r\n*weeb* oh wow\r\n*o* i think my favourite is DSCN2855.jpg\r\n*weeb* they\'re all perfect\r\n*o* the sunrise was so perfect\r\n*s5* it was the most amazing sunrise ever\r\n*s5* it was right around the solstice so the sunrise kept going\r\n*s5* forever\r\n*o* mm it was so beautiful\r\n*o* during the night before the sunrise, s5 stopped somewhere in\r\n*o* victoria in the middle of nowhere, the stars were so bright\r\n*o* they felt so close\r\n*o* i could have stared at them forever, but the bugs were making\r\n*o* scary noises.\r\n*weeb* haha\r\n*s5* everything in australia is venomous\r\n*weeb* one to one relationship between bug ferocity and beauty\r\n*weeb* of the land\r\n</tt></pre>\r\n</p><p>\r\n...\r\n</p><p>\r\nwhat was the most beautiful sunrise you\'ve ever seen?\r\n</p>'),(2526,'my mother used to collect fish scales. she would place them in a clean glass jam jar, over the kitchen sink, where a single beam of sunlight would illuminate the raspberries on the fading label. i would watch the gleaming, rainbow-in-oil-spill pile, composed of scales the size and shape of my child fingernails, grow slowly but steadily over the course of many months. she would take such delight in this jar, picking it up and admiring it for hours at a time.\r\n<br><br>\r\none day, while doing the dishes and talking to her best friend on the cordless phone at the same time, my older sister accidentally knocked the jar off its little metal shelf. it shattered. my sister gasped and covered her mouth with her palms, the soap bubbles drifting through her fingers and down her chin. none of us dared to look at our mother. i didn\\\'t know i was holding my breath until it came bursting out, just as the french windows to the back garden closed. my mother had left the room, in silence. \r\n<br><br>\r\nmy mother was an enigma. we thought, but were never sure, that she had a strange and exotic disease. she never mistreated us, but often we felt like either we were aliens or orphans. there was always a sadness to the edge of her small upturned nose and big eyes. now i torture myself, think that she was trying to tell us something all along, while she ironed our summer dresses, and wrung chicken necks out in the yard in that oddly precise, mechanical way that never failed to startle me. she was sending us girls a message, and we didn\\\'t know the code to decipher it.\r\n<br><br>\r\ni don\\\'t have a single memory of her smiling at people. the only times i saw her lips curve, dreamy, sensuous, softening till they looked like a young girl\\\'s, was when she was asleep, or looking at animals. i remember her glowing as she walked among the pigeons on our roof. a young male neighbour, with coffee coloured skin and strong arms, who i realise now must have been infatuated with her, built us a great networked bird house, with many rooms. i would follow her up the unpainted stairs, and watch as she scattered the bird seed.\r\n<br><br>\r\nthen there were trips to the hospital. and tiny breaths. once while she was away, i sneaked a look at the cloth journal in her underwear drawer. it was completely blank. but there, beneath the package of sanitary napkins, and an unopened box of chanel no. 5, were four watercolours:\r\n<br><br>\r\n\\\'girl carrying a basket of bread and daffodils\\\'\r\n<br><br>\r\n\\\'the push of wings beneath his elbows\\\'\r\n<br><br>\r\n\\\'old woman pining for the use of her limbs\\\'\r\n<br><br>\r\n\\\'sparrows at the moment of their death\\\'\r\n<br><br>\r\nthe faces in each painting had my mother\\\'s eyes. no, that\\\'s wrong. they had the look she would get in her eyes. a certain way of seeing, that made you think she was in a world that was locked to the rest of us.\r\n'),(2527,'it makes me sad when i think about all the friendships i have lost over the years. the people i knew in elemetary school, the people i knew in highschool, the people i even knew since then. the closeness that i felt to them was immense. the tightly bound feelings and ideals and methods for expression are what i miss the most.\r\n<p>\r\ni miss the feeling of being loved by a close friend. knowing that they\\\'ll be there no matter what happens. i remember a time my best friend came to visit me when i had chicken-pox. he had never had them before and risked getting them too.\r\n<p>\r\nwell, i guess friendships are fleeting. new experiences do shape every person individually and no matter how hard you try, you never quite change in the same way or at the same time. it\\\'s too bad that we don\\\'t, while being one of the most wonderful things in life.\r\n<p>\r\nwhether you lose a friendship because you grow apart, fight or break it off, there is still always a piece of your life missing. i fondly miss the times playing in the park with my best friend when i was five in the same way i miss a friend that i dated in highschool who moved to british columbia to go to university. the same distance exists in my mind. the years and stories of my life have changed who i am and who they are in ways that neither of us will really understand no matter how long we spend catching up.\r\n<p>\r\ni just wish i didn\\\'t get so melencholy about losing friends. today it is the fear of losing a friend that really takes me down. it\\\'s really the fresher friendships that i don\\\'t want to lose, that i fear i am losing to time. i have dealt with the old ones; the ones that i can just pine over years later.\r\n<p>\r\nreally, it is just a part of life. to experience the loss of someone close. losing family or friends is the most difficult change to deal with that i have ever experienced in my short life.'),(2528,'<P>library\r\n</P>\r\n\r\n<P>it is handled like\r\n<BR>the radio</P>\r\n\r\n<P>includes\r\n<BR>search\r\n</P>\r\n<P>a volume\r\n<BR>once history\r\n</P>\r\n<P>graphic fields\r\n<BR>of manual</P>\r\n\r\n<P>settings</P>\r\n\r\n\r\n\r\n\r\n\r\n'),(2529,'<P>\r\nOK EVERYBODY LISTEN UP FOR THE RULES!\r\n</P>\r\n<p>\r\nthe first and most important rule is the goggle rule. while you are out in the field goggles must be on at all times.\r\n</p>\r\n<p>\r\nthis is what \\\'goggles on\\\' means. *put goggles on*\r\nanything other than this is considered off. this is off. this is off. this is off. \r\n</p>\r\n<P>\r\npaintballs travel at about three hundred and fifty feet per second(anyone whose played knows this is wrong, but we like to scare them a bit). if you were to get hit in the eye without having your goggles on, you will lose it.(this is true, and has never happened where i work) the possibility of brain damage is also there(maybe), so keep the goggles on at all times. if goggles are off once you sit a game. twice yer gone. \r\n</P>\r\n<P>\r\nthe second most important rule is the barrel plug rule. barrel plugs come in all sorts of shapes and colours. they stick out of the end of the barrel so that no one can be shot in the eye while in the safe area(the area im telling the rules). if you come through that door without a barrel plug, you will sit a game. twice and you are done. remember the barrel plug. \r\n</p>\r\n<p>\r\nwhen you are out there you are going to see that it is a bit slippery. for this reason please be careful. dont expect to make a turn if you\\\'re running at top speed. you are going to keep sliding. no diving through windows. no jumping off the balcony. stairs are the only way up and down. on the second floor, please watch your head. there are some pipes and lights that hang low. \r\n</p>\r\n<P>\r\nDO NOT. I REPEAT DO NOT pick paintballs up off the ground. some of them have been out there years, and they can either turn into sponges or marbles. eitherway you are going to wreck the gun, and/or hurt someone. if we catch anyone picking paint off the ground and putting in their gun, yer outta here.\r\n</P>\r\n<p>\r\nanyone and anything out there is a target except for the ref and the lights. we catch anyone shooting at either and you will be outta here. the ref is out there to help you and make sure things remain safe. the lights are also out there to help you and keep things safe. if we catch anyone unplugging/tampering with lights you will sit a game. \r\n</p>\r\n<p>\r\nuse your common sense when you are out there everyone. remember that it is a game and everyone out there is out there to have fun.\r\n</p>\r\n<p>\r\nany questions?\r\n</p>\r\n<p>\r\nok if there are no more questions, id like to ask everyone to come over here and grab a vest. half go green, half go red. \r\n</p>\r\n<p>\r\nok. everyone come grab a pair of goggles. keep these with you at all times.\r\n</p>\r\n<p>\r\nok, we are going to start handing out guns. the guns are all semi-automatic. this means that with every pull of the trigger, one paintball will fire. when i hand you your gun, please hang onto it by the air tank. this way no one can pull the trigger by accident. \r\n</p>\r\n<p>\r\nOK, WHEN EVERYONE IS READY, MEET THE REF OUT ON THE FIELD, AND HE WILL GET YOU STARTED ON YOUR FIRST GAME!!!\r\n</P>'),(2530,'I\\\'m coming out. Not that I\\\'m gay although sometimes I wish I was (grass always seems greener on the other side). This declaration is related to me being subversive. I do not like the established order of things and when given the opportunity I will promote activities aimed at undermining this. Sometimes these activities are criminal, sometimes they can be a real annoyance to people that don\\\'t know my reasoning, sometimes they can be an annoyance to people that do know my reasoning, and often they are some of my most joyeous moments.<br><br>\r\n\r\nMy motivations are diverse and I\\\'m willing to admit they are not <i>always</i> justifiable.  I\\\'m not an angst ridden teenager anymore so we can scratch this as the reason I behave in such a manner. We could say that I have fallen victim to some hardcore indoctrination by anarchist revolutionaries (I would like to romanticize it by thinking this was it) but truth be told I have worked for the civil service and have a strong dislike for dogma or doctrine regardless of source. I believe in the virtues of liberty and justice (not law) above all others. On my fathers side of the family the last 5 generations of men in my family have been in the military and my mothers side of the family is a long line of community politicians. I often think about these things when I\\\'m in the process of committing some act. <br><br>\r\n\r\nI remember the talk from my father about what is important in life and how you are suppose to fight for what you believe in (his actual words were something along the lines of \\\"kill and die\\\" but seeing as how I\\\'m not in the military I try not to take this too literally).  My mother kept me in check a bit by instilling values that follow the social democrat tradition of her family (having worked for the government though I have serious doubt about the democratic part of her values). I love my parents but to be honest they are both a bit far from their own marks if you get my drift. My father unless you directly challenge him would sooner just leave things be really. My mother is simply too up tight and concerned with keeping up with the jones\\\' to be described with the open acceptance stereotypical of a social democrat tradition. As for me I\\\'m just a subversive brat but I think I\\\'ve said that once already.<br><br>\r\n\r\nI listen a lot to other people when they complain about how things work. Some rally against the openly political others are upset by social or economic issues that are not as overtly political (apolitical or apathetic types are fond of the latter). A lot of people make excuses for the way things are, others do a cost benefit analysis and think they have more to lose then gain, and more still simply don\\\'t want to deal with the confrontation that accompanies any sort of change big or small. So why can\\\'t I just slip myself into one of these categories?, I\\\'m sure nobody else would really notice or mind. <br><br>\r\n\r\nOne word seems to fly out at me as I ponder this <b>banality</b>. I think that western society has really lost something and I want to find it again. It isn\\\'t the erosion of family values that so many right leaning politicians moan about and it isn\\\'t the never ending list of inhumane acts that the left rightfully brings up. I think we (this being the royal, collective, generalizing we) have lost our spirit, the intangible quality that used to make us collectively strive towards and realize monumental goals. We like security over liberty and are champions of indifference when it comes to justice unless it impacts us. [note : in the current climate I realize this might be a bit scandalous but my feelings predate the terrorist attacks - just look at issues of civil liberties online in an increasingly wired world]. <br><br>   \r\n\r\n I\\\'ve often been told if you don\\\'t like things you should go somewhere else to get some perspective. It is amusing when I reply with the fact that I have lived else where and if not for economic hurdles and immigration laws might leave again. Next it is mentioned that I have just as much right to stay put and that maybe they should leave. I always imagine walking outside of where ever these conversations take place and having a pissing contest with the person judged on volume, aroma, and speed.<br><br>\r\n\r\nThe subversive acts can be as mild as vandalism or as harsh as violent confrontation with authority figures. I don\\\'t expect most people to understand but I think of these acts as the lesser of two evils. They are the catharsis that allows for the venting of my accumulated rage that I feel due to a collective malaise in western society. Just to clarify I\\\'m not the sort that is saying the west is completely despicable, far from it. I just think that we aren\\\'t doing all that we can for ourselves or other cultures. The cathartic effect of some of these subversive acts stops me from being a complete ass to random strangers that I have a tendency to connect with society at large instead of looking at the individual.<br><br>\r\n\r\nMaybe I\\\'m criminal, maybe I\\\'m juvenile, maybe I need psychological help, or maybe nothing is wrong with me. I just seem to have an over abundance of rage related to feeling out of synch with society around me. The banality of even this rant if I think too much about it is brutal. Will I ever be happy/satisfied? No, because I always want progression, there are plenty of other people that will take my share of the happiness. I\\\'ll make due with my moments of joy from my feeble attempts at throwing off the choke hold of banality.<br><br> '),(2531,'barely any light</br>\r\nbarely any light to see</br>\r\nwinds foreshadowing clash</br>\r\nwinds blowing against</br>\r\nagainst</br>\r\nagainst\r\n<p>\r\nsit and look at me</br>\r\nsit and don\\\'t speak</br>\r\nwrapped in white sheets</br>\r\ndon\\\'t get up and leave</br>\r\nplease</br>\r\nplease\r\n\r\n'),(2532,'<P>\r\nyou need to find a partner.  look the crowd up and down.  find someone who seems to have status.  if you are just bored, take a shot in the dark.  if you are on a mission, look for the nicely dressed, or well known.  \r\n</P><P>\r\nto some the first move is not obvious, but it should be.  there are several approaches.\r\n</P><P>\r\n_ walk up and insult them, then see how they react\r\n</P><BLOCKQUOTE>\r\n    ex.: what foreign country did you pick those shoes up in?\r\n</BLOCKQUOTE><P>\r\n_ find something to criticize, be it a performance, work, clothing, or weather\r\n</P><BLOCKQUOTE>\r\n    ex.: you would think the interactive conference would have internet ports available for the panelists.\r\n</BLOCKQUOTE><P>\r\n_ ask a question seeking clarity\r\n</P><BLOCKQUOTE>\r\n    ex.: are you waiting for the i-mode panel to start? i\\\'m not sure if i\\\'ll stay for this or go to josh praystation\\\'s presentation.  it is really a question of corporate demo or art.\r\n</BLOCKQUOTE><P>\r\n_ present yourself as helpful \r\n</P><BLOCKQUOTE>\r\nex.: i heard EFF is starting a new library on internet\\\'s threatening laws.  i wrote software to manage libraries, we are thinking about open sourcing it.\r\n</BLOCKQUOTE><P>\r\n\r\nsee how simple it can be?  all of the above are real world examples that distilled for essence will help you out tramendously in situations where you need to <i>make the first move</i>.  \r\n</P>\r\n<P>\r\nnext, advanced topics in networking with special guest <a href=\\\"http://links.net\\\">justin hall of links.net</A>! <BR>(japanese support required)\r\n</P>\r\n'),(2533,'<a href=http://swinney.org/journals/article.phtml?id=2306.txt\\\">previous page (7)</a>\r\n\r\n<p>he took away his arm from his face and squinted his eyes until they were comfortable with the light.  he felt warm, and took in his first full breath inside the dream.  the flash of memory of every other first breath he had drawn in previous hosts passed through his thoughts, simultaneously.  it was pleasant, and he looked forward to it every time.  two small grass covered hills rolled between him and the tree where the woman was sitting.</p>\r\n\r\n<p>she had seen him appear, standing up amongst the grass, covering his eyes.  she wondered if that was what she looked like whenever she came through the window for the first time.  the light always seemed to be different for every host - no way to get used to it.  she felt calm as she watched him start toward her.  </p>\r\n\r\n<p>he was hesitant at first, but stepped forward, more confidence with each step, likely from more breaths cycling the dream into him.  the grass washed around his footsteps, his footsteps made her slide closer to him.</p>\r\n\r\n<p>a cicada in the trees above the woman watched down as the man approached, hummed electric tones to the leaves in the tree and anything else that could hear.  the man stepped to the base of the tree, beneath the canopy, and listened to the cicada while his eyes looked to hers.  neither had met another of their kind in a situation anything like this before, but both felt comfortable.  he stood in front of her, she looked back from her seat against the tree. </p>\r\n\r\n<p>she opened her mouth to speak, but felt her breath pushing words only just past her lips, until they were saturated by the sounds around her, immediately diffused into the wash of the tree and grass, caught in the throat of the cicada, not even reaching her own ears.  the man\\\'s words were lost just as quickly; he also could not speak.</p>\r\n\r\n<p>he studied her face, slender, plain, and calm.  her skin was rich with sunlight, her hair absorbed it, darker and warmer, resting straight upon her shoulders.  he moved his eyes up along her cheekbones and saw them shape like the branches that reached out over them both.</p>\r\n\r\n<p>he quietly crouched down.  he put his hand to the grass, felt a stray twig bend under his palm, turned and backed up to sit beside her.  she turned to look at him, and was peaceful.  he thought about her, who she was when she was awake.  she knew he was of her kind, and wondered how they would come to know each other.</p>\r\n\r\n<p>he broke his eyes from hers, and looked out to the horizon, saw that the sun hadn\\\'t set anymore, and that it would stay that way whenever he was there.  she looked out as well, and breathed in as his arm passed from her view, behind her.</p>\r\n\r\n<p>tracing languid paths with absent fingers, ploughing ribs and spine, he wrote his hands into her skin.</p>\r\n\r\n<a href=http://swinney.org/journals/article.phtml?id=2306.txt\\\">previous page (7)</a>'),(2534,'I just woke up my best friend\\\'s dad.  This is a guy that I\\\'ve known for 15+ years, and I could hear him cursing in the background at me as he walked down his hallway (which I know every inch of) to see if she was awake.  Apparently, she wasn\\\'t.  This is despite her saying that I should call her at any time, and that she\\\'d have the phone right by her bed. \r\n\r\n<BR><BR>\r\n\r\nShe is 700km away from me right now, but it feels like 7million.  She\\\'s got a job with the most prestigious agency in the country in her chosen field for three weeks, and that\\\'s an absolutely amazingly wonderful opotunity for her, and I am so happy for her, but there\\\'s a huge part of her that wishes she was still here in my city. I am lonely.  I had a fight with someone else tonight and I\\\'m trying to find a sympathetic ear.  The guy that i normally talk to in this kinda situation isn\\\'t  answering his phone.  My flatmates don\\\'t have anywhere near the level of empathy that I need. \r\n\r\n<BR><BR>\r\n\r\nI guess everyone has these moments, when you\\\'re sitting up late on the internet because it\\\'s better than lying in bed crying.  Maybe there\\\'s no one online on your ICQ or AIM lists because everyone you know is in  a  different timezone or actually sleeps decent hours, so you feel completely alone.  I mean,sure, during  daylight there are a dozen people a phone call away, but  what about the here and now?  All I want is an AIM, or an ICQ, or even an SMS (+64212127920).  But instead, I\\\'ll just try and sleep, and  hope that I feel better tomorrow.\r\n\r\n<BR><BR>\r\n Self pity sucks, especially when you can\\\'t stop wallowing in it. '),(2535,'<br><br>\r\nthe gulls migrate in great black waves through the dense white sky, escher in motion. on thursday afternoon several hundred of them were diving and soaring from a small canopy of evergreens next to the park \\\'n ride, first whirling down into the frail autumn leaves with great force, and then swooping up high high high, so fast you could see the acceleration, you could get dizzy just watching. \r\n<br><br>\r\nwaiting for a 95 at baseline station, i was quite a few metres away. it looked like a giant was furiously shaking pepper - the birds scattering, a seasoning - on his enormous leafy salad. \r\n<br><br>\r\nthis morning i was closer. i could see all their wings flapping furiously, like bendy black propellers. they looked like they were rotating, in sync, clockwise. although a few seemed to be going anticlockwise. i hardly saw any birds alone. there were just many many groups of birds. and they didn\\\'t fly in perfect Vs. Ls maybe. even a W. the lengths of birds were often wobbly, had one diagonal longer than the other, or the bottom angle made of four birds instead of three. \r\n<br><br>\r\ni know all about the benefits, the added lift, the shared strength of flying together in such a formation. but how did they choose which group to join? all the birds looked alike to my too-human eyes, but surely they were not interchangeable. did they have friends? did they make specific plans? let\\\'s go to costa rica next moonrise, you and me, and white tail. we\\\'ll ask shiny-eyes if his family wants to come along as well? \r\n<br><br>\r\nas i was watching, about nine Canadian geese suddenly alighted on the football field and i stared at their plump bodies in amazement. how could their small wings bear so much weight? imagine a butterfly carrying a pillow strapped on its back as it flew thousands of miles on its long journey south. \r\n<br><br>\r\ni have to admit i\\\'m tired of watching explosions on a small dark screen, of tracing maps of afghanistan lit up in red. out of all the questions, i let only one enter my mind: of all the birds i\\\'ve seen in the last few weeks, how many will make it, will reach their destination, in safety? \r\n<br><br>'),(2536,'<p>r9 (11:14:17 PM): yeah I have a thing for cumming and providing plenty of uses for it<BR>\r\nfelicity (11:15:22 PM): I think the last time you left my apartment, there may have been some on my ceiling. (Is textured wall covering a legitimate use of splooge?)<BR>\r\nr9 (11:16:02 PM): yeah I still cum a lot<BR>\r\nfelicity (11:16:21 PM): a fine quality, indeed.<BR>\r\nr9 (11:16:28 PM): A few years ago I got a blow job, standing up, and came in my own eye<BR>\r\nfelicity (11:17:03 PM): not every guy can claim that kind of water pressure.<BR>\r\nr9 (11:17:19 PM): well I\\\'ve done a lot with cum in order to spice things up<BR>\r\nfelicity (11:17:56 PM): you make it sound like arts and crafts materials.<BR>\r\nr9 (11:18:37 PM): well I worked at a smut store for a couple of semesters and while I was there, I put together \\\"How To\\\'s\\\" for newbies<BR>\r\nr9 (11:19:08 PM): Bondage 101, intro, rules, safety, what you\\\'d need, games, and a list of ideas.\r\nr9 (11:19:14 PM): all sorts of stuff like that<BR>\r\nfelicity (11:19:16 PM): ahhh. it\\\'s amazing what you can learn in a few months in the adult entertainment industry.<BR>\r\nr9 (11:19:21 PM): oh yeah</p>\r\n--------------------------------\r\n<p>Two things:<BR>\r\n1. Define \\\"a lot of things\\\" when it comes to doing stuff with semen.  I\\\'m a fairly creative person, but \\\"a lot\\\" might be stretching it.<BR>\r\n2. Why didn\\\'t we ever get to diagram sentences like \\\"Is textured wall covering a ligitimate use of splooge?\\\" in elementary school?(Ok...I know why, but still, what prepapres a person to have a conversation like this.)</p>'),(2537,'she saw a glitter off in the distance, at the horizon. a flash, as if it was a mirror. i thought she was just kidding, but reluctantly i agreed to start in that direction. in the heat of the mid-afternoon sun, i didn\\\'t want to do anything much, but what choice did we have?\r\n<p>\r\nwe made our way across the barren landscape avoiding tripping on the strange tufts of dry grass poking up through the parched red soil. dust was spinning around our feet and into drifting clouds behind us. we must have almost looked like a rust-coloured storm front as we traveled. the light of the day was waning and the sky was beginning from topaz to regal purple and blue.\r\n<p>\r\nthe glittering was distinct now, even to me. it was coming from a small outcropping below the darkening sky. i\\\'m sure now that if the sun hadn\\\'t been behind us, we\\\'d never have seen them. sometimes i just wish we hadn\\\'t.\r\n<p>\r\ni\\\'m sure you understand now why we would have been better off finding shelter someplace else. i suppose it doesn\\\'t matter anyway since this is where we are now. then again neither of us are exactly desert folk.'),(2538,'<p>There were always several Maasai men hanging around our camp site and the lodge area, draped in their red cloaks, sometimes leaning on their spears looking quite regal and proud, but always smiling and always greeting us with a friendly â€œJambo.â€  We were told we could hire one of them to accompany us on a walk inside the reserve.  â€œSince they can smell the elephants and lions, and heâ€™ll have his spear with him, youâ€™ll be very safe.â€, we were assured.\r\n\r\n<p>So on the second afternoon of our safari, we met 38-year-old Narok, who looked every bit the Maasai warrior...lean, strong, and confident.  But as we started our walk, we also quickly discovered his warm smile, gentle nature and engaging ways.  He wore the traditional garments and carried a club, a fierce-looking knife and the long spear that all Maasai adult men â€œnever leave home withoutâ€.  We felt comfortable and secure with him, despite the fact that we were now venturing out into â€œdangerâ€ without the protection of our van, and certainly without an AK-47!  It is clearly an entirely different experience exploring the Serengeti Plains without the insularity of metal and glass surrounding us, and striding past the footprints and dung of animals that could be potentially life-threatening, not knowing what might be lurking in the bushes, is most exhilarating.\r\n\r\n<p>Shortly after we left the camp, Narok stopped and carefully listened to the sound of nearby cowbells.  â€œThatâ€™s my cow....itâ€™s lost...Iâ€™ll be right back.â€, and off he ran, loping off with a stride that he later bragged could carry him â€œ20 km in an hourâ€, surely a bit of an exaggeration, as world-class marathoners cannot maintain that pace.  But, then again, who knows?  \r\n\r\n<p>After returning a few minutes later with problem solved, we walked on, soon coming to an abandoned Maasai boma (village).  Since they are nomadic, the families often leave their primitive dwellings and move their cattle elsewhere in order to find better food and water sources.  â€œThis isnâ€™t needed anymore.  Do you have a lighter?â€  He had inspected the surrounding grass and deemed it safe to start a fire, knowing it wouldnâ€™t dangerously spread, since it had rained a great deal the previous two weeks.  Minutes later a a huge fire was raging, consuming what had once been someoneâ€™s humble abode.  It was now being returned to Mother Earth.\r\n\r\n<p>With smoke billowing upwards behind us we walked on, threading our way along narrow paths among the brush, bushes and trees: jacarandas, flame trees, cactus-like candelabrias, and the ubiquitous thorn trees (acacias).  Another tree we found fascinating, and certainly unique, was the sausage tree, understandly named due to its long sausage shaped fruit hanging from its branches.  We occasionally passed enormous mounds of red earth made by termites as we headed toward a prominent ridge, where an hour later we reached a viewing point from which we could overlook the entire valley.  The view was stellar...the spendor of the African grasslands in all its glory!  Dripping with sweat, we sat on rocks and took it all in as we drank from our water bottle.  We offered him some, but he politely declined.  â€œDonâ€™t you get thirsty?â€, Heide asked.\r\n\r\n<p>â€œI never drink water.â€, he explained.  â€œEvery day I drink four liters of milk...thatâ€™s enough.  And on Fridays, we mix in blood from a cow....that gives us plenty of strength!â€  It is reported that the Maasai also mix in their own urine...maybe he was reluctant to add this, thinking it might be more information than we wanted to know.  (And to think that I apparantly wasted so much money over the years making up my â€œenergy drinksâ€ in my blender with juice, yoghurt, brewers yeast and pee pollen!)\r\n\r\n<p>We relaxed and talked about life these days for his people.  It is a hard life, as it is for many people of Africa.  â€œYou know we have to pay to send our children to school.â€, he said.  â€œIt costs a lot.  We cannot afford to send all our children, and besides that some of them need to stay at home to watch the cattle.â€  \r\n\r\n<p>And family life?  Narok has two wives and six children.  We asked how men and women come together as husband and wife, and he informed us that when a man wants to marry, the father of the prospective wife is told of this choice, and he then informs his daughter, who might be as young as 12 or 13.  â€œIf she doesnâ€™t like the man and doesnâ€™t want to marry him, can she refuse?â€, asked Heide.\r\n\r\n<p>â€œSure she can say no.â€, he responded.  â€œAnd after three months sheâ€™s asked again and if she still says no, the father kills her.â€\r\n\r\n<p>Sure she can say no!  \r\n\r\n<p>I asked him about the legendary hunting skill of the Maasai and whether they do in fact sometimes kill lions with only the basic weapons they carry.  â€œIf we need to....sure no problem.â€.  Apparantly the age-old practice of killing a lion to â€œprove youâ€™ve become a manâ€ or as a requirement for each marriage is dying out, discouraged (for good reason) by the rangers, since the lion is under threat like much of the African big game.  But these people do live on Simbaâ€™s â€œturfâ€, and protecting their families and valuable cattle from Public Enemy Number One is still their responsibilty.\r\n\r\n<p>He said that yes he had killed lions, and to demonstrate the efficacy of his weapon, he pointed, â€œSee that bush over there?â€  It was about 20 meters away.  When we nodded, he let fly with his heavy, but razor-sharp spear....bullseye!  â€œIt will go clear through the lionâ€, he said convincingly, and we had no reason to doubt it.  â€œAnd we also have our knife to finish the job if we need to!â€, he grinned.  Though later he added, â€œ  But once in a while when a man goes out to kill a lion that is eating his cattle, he never comes back.â€  \r\n\r\n<p>Narok did seem to have made some concessions to the modern world.  He was wearing very modern walking sandals (Birkenstocks?), as well as very smart-looking shorts under the traditional clothing.  He also had a set of keys hanging on a thin cord around his neck.  Heide and I speculated that possibly these were used for locking up his ten-speed bike?\r\n\r\n<p>The next morning we headed out for another game drive.  Although it warms up considerably during the day, at dawn we bundled up against the cool air as our van meandered through the reserve, each pair of eyes searching, each pair of hands (except mine and the little girls) clutching a camera in anticipation of another â€œgreat shotâ€.  Once again we struck gold!\r\n\r\n<p>A mother cheetah and her four nearly mature cubs were on a hunt!  The target: a herd of Thomsonâ€™s gazelles.  The gazelles were well aware of the cheetahâ€™s presence as they grazed.  As the mother slowly moved closer, the herd would also ease away, always closely watching her, keeping a safe distance away.  The cubs were observing intently, clustered together several meters behind their mother/trainer.\r\n\r\n<p>But then, as if by some unacknowledged pre-arranged signal, the cubs suddenly moved as a group, slowly spreading out, creating a line, each cub about 20 meters apart along one side of the herd.  The mother remained still, crouched down in the grass.  The cubs continued to move, now in full view of the gazelles.  â€œThey are confusing the herd.â€, our driver George informed us.  â€œThe gazelles donâ€™t know which cheetah to watch.â€   Then the cub farthest from the mother eased into a gentle trot towards the herd in an effort to direct them back towards mom.  The strategy worked, as some of the gazelles took off, angling somewhat toward the mother.  Gazelles are fast...real fast!  But as you probably learned as a kid in school like I did, the cheetah is the worldâ€™s fastest land animal, capable of reaching speeds of up to 110 km/h (75 mph).  They canâ€™t maintain that speed for more than about 100 meters, but in this case, the mother needed far less than that to overtake one of the gazelles...apparantly the slowest one (Darwinâ€™s theory at work here).\r\n\r\n<p>Because the culmination of the chase took place behind some brush we didnâ€™t see the actual kill.  But our vehicle quickly headed off in that direction, and we soon came upon the cheetah clutching the gazelleâ€™s neck, panting heavily.  We stopped and turned off the engine, and soon the cubs appeared.  The mother dropped her prize, and stood sentry watching for other predators, as the cubs commenced with their breakfast.  â€œGuten appetit.â€, I thought silently.  From no more than 3 meters, we silently watched for about 30 minutes while they fed.  Then, after the cubs had had their fill, the mother settled down to take her turn, and the cubs with their blood-smeared faces took turns watching for lions, hyenas, etc.   It was all so amazing to witness in such close proximity!\r\n\r\n<p>After three nights at Masai Mara it was time to move on.  Our Norwegian friends, Kris and T.J., left us, as did the Japanese man Yoshi.  With Ruth and her two girls, aged 3 and 5, and our new driver Elly, we headed to Lake Nakuru National Park.  140 miles northwest of Nairobi and a half-day drive from Mara, it was established in 1960 as the first bird sanctuary in Kenya.  Back now in the Rift Valley, this lake is one of many shallow soda lakes formed when springs bring sodium carbonate up to the surface, and with poor drainage and evaporation, leave a high concentration of alkaline deposits in the water.  Evidence of â€œsalt farmingâ€ is seen along the roads in the area, and the algae and crustaceans which thrive in these soda lakes are ideal food for the flamingos that congegarate there.\r\n\r\n<p>These enormous flocks of pink flamingos can number up to one million, and to see them all wading in the lake is quite a sight.  Itâ€™s been dubbed â€œthe worldâ€™s greatest ornithogical spectacleâ€.  We spent a night at a lodge in town, got up at 5:30, and headed into the neighboring park with Elly, a tall, slender 34-year-old Luo, who carried himself with quiet but self-assured confidence.  From this point on in our safari, we would have him all to ourselves.  We first drove to the lake, where many pelicans joined the flamingos in the water, as they fed, preened and occasionally honked.  Here we could get out of the van and view all the birds....a sea of pink!   Apparantly it is really something to see the flamingos lift off of the water and fly over, and I was silently praying that a vehicle might noisily backfire, startling a few hundred thousand of them upwards.  But it was quiet, peaceful...and beautiful none-the-less.\r\n\r\n<p>One reason I wanted to come to Lake Nakuru was that it is one of the few remaining places where there is still a good chance to see rhino, as poaching has seriously decimated their ranks throughout East Africa.  Surrounding the lake are forested areas, grassland and rocky cliffs, and encircling the small park is electric fencing to protect the rhino from the kind of low-life scum that brutally slaughter them for profit.  The rhinoâ€™s numbers in Kenya have dropped over the last 30 years from around 200,000 to about 500.  I donâ€™t know who are worse, the poachers who kill the rhino, or the morons who support this heinous crime by buying the end-product with some kind of illusion that it provides an effective aphrodisiac.  I am firmly against capital punishment, but I say throw them ALL into a squat toilet together, lock the doors, and then force them to listen to blaring techno music for the rest of their natural lives!!!\r\n\r\n<p>The rhino fascinates me as much as any animal that exists.  Itâ€™s appearance is that of a strange hybrid of prehistoric monster and modern military tank.  It is extremely near-sighted and ill-tempered and can weigh over 1600 kg (3500 lbs.)....hell on wheels!  Both varieties, the so-called black and white rhino (they are actually different shades of gray), reside in small numbers in the park, and we slowly drove along eager to spot at least one.  I still needed to â€œbagâ€ both a rhino and a leopard to complete my Big Five/Big Nine.  I had no intention of buying and parading around in a tacky teeshirt, like some tourists do broadcasting their â€œaccomplishmentâ€, but I did want to see them.  Can you blame me?\r\n\r\n<p>First we saw giraffes up close, foraging from the trees.  These were what are called the reticulated giraffe, differing in both coloring and pattern from those we saw at Mara...kind of a tortoiseshell pattern.  Magnificent!  We moved on.  Immediately next to the road was a cape buffalo.  We were so close we could hear it munching the grass.  On its back was a cattle egret, which feeds on locusts, flies and grasshoppers that appear as the buffalo walks, churning up the soil.  The buffalo and us nervously eyed each other.  Widely considered by hunters as the most dangerous of all the big game to hunt, it tips the scales at 800 kgs, has those imposing and distinctive curved horns, and will get no votes either for Mr. Congeniality!  Having him thundering at us would be no joke!  We moved on.\r\n\r\n<p>And then we saw a rhino.  And then another.  And soon there was a group of 12, both varieties, calmly chowing down their lunch just a few meters from us!  â€œGod theyâ€™re bigâ€, I thought.  I was totally mesmorized!  They totally ignored us.  Then we heard Ellyâ€™s quiet but excited voice, â€œLook...here comes a leopard...a big male!â€  And sure enough, less than 10 meters away was what I think is Africaâ€™s most beautiful animal.  He had spotted a herd of impalas and was making his way towards them, and his path would take him directly behind and fairly close to the rhinos...who ignored him too.  A solitary and illusive animal, the leopard normally hunts at night and is quite difficult to spot.  Sometimes it is seen lounging along the lower branches of the acacia trees during the day, where it might have pulled up its kill.  The leopard is so strong that it can drag twice its own weight up into the branches to keep his hard-earned dinner from getting swiped by lions, which are much bigger, or hyenas, which often travel in packs. \r\n\r\n<p>But â€œluckâ€ was with us again.  Here in broad daylight was a magnificent male bearing down on his prey.  But this time he would have no luck as the impalas had either seen or smelled him, and kept moving just far enough away from him to foil his plan.  Not as fast as a cheetah, he must make his charge from quite close to bag his prize.  But we had surely bagged ours!  Chalk up the Big Nine for us, and, what was even more remarkable was that Heide got photos of both the leopard AND the rhino at once.  Two for one!  Hot damn!\r\n\r\n<p>That day we would leave Lake Nakuru National Park and head yet farther north to Samburu National Park.  Our travels would take us past the equator and allow us to discover first-hand the answer to one of our long-held questions: does water really spin the opposite way south of the equator when it goes down the toilet?\r\n\r\n<p>So far in our time south of the equator we hadnâ€™t seen whether or not it did, since we hadnâ€™t actually been around a flush toilet yet that worked!  But right at the equator itself we were provided with a dramatic demonstration...for a small fee, of course.  A young man with a carefully rehearsed canned presentation walked off 20 meters in each direction from the equator sign, each time dropping match sticks into a funnel filled with water which ran into a pail.  He then repeated the act directly at the sign.  Clockwise...then counter-clockwise...then no spinning at all.  We were given written certification documenting our attentance of this scientific feat.  I could now live out the balance of my life fulfilled, knowing that I now had direct, empirical knowledge regarding the answer to one of the age-old mysteries of the cosmos.\r\n\r\n<p>I gave serious thought to calling article â€œOff the Roadâ€, rather than â€œOn the Roadâ€, since our time in vehicles was spent as much off the roads as on them, and when we were on the roads, if actually felt more like being off.  Our roads north, as is true with most roads in Kenya, could best be described as appalling!  Despite this country having enormous natural resources, corruption throughout the government has resulted in a seriously deficient infrastructure.  As we bounced along, sometimes slowing to a crawl, Elly turned and commented, â€œOur roads here arenâ€™t so good.â€  I would say that this is a classic understatement of massive proportions!    \r\n\r\n<p>At many times, our drivers were better off driving the shoulder of the so-called road for substantial distances, since the actual road was in such a sad state.  They would usually have to make choices on which potholes to drive through, as avoiding them altogether was impossible, unless one had a hovercraft!  Riding five hours in Kenya is roughly equivalent to spending five hours on the back of a bucking bronco with hiccups, and itâ€™s a miracle that we had only one breakdown and two flat tires during our month cruising around East Africa.\r\n\r\n<p>Absolutely the dumbest idea in Kenya: speed bumps.\r\n\r\n<p>Organizations such as the IMF and World Bank, and the various international aid agencies, are now extremely reluctant to loan or donate money for development in Kenya, since they know that virtually all of what they give eventually ends up in a Swiss bank account of some dirtbag politician, rather being spent on providing something of benefit for the 30,000,000 people of this country.\r\n\r\n<p>And democracy has been somewhat of a sham more often than not.  Since Kenya gained independance from Britian in 1963, there have only been two presidents, and the current one, Daniel Moi (whose photo is displayed in all public places by law) has been in power since 1978, at times only due to the suppression and intimidation of political opponents and elimination of any opposition parties...it is hard to lose an election when you are the only party allowed!\r\n\r\n<p>What the world is witnessing now in Zimbabwe, with Robert Mugabeâ€™s strong-armed tactics and manipulation of the political process, has been all too common throughout this entire continent since the yoke of colonialism was thrown off, country after country, in the â€˜60s,  and Kenya has been no exception.  Bribery, corruption, conspiricies, attemped coups, political assassinations, rigged elections, tribal favoritism...even the banning of the secret ballot for some time...this is often â€œbusiness as usualâ€ among those who hold power here.  It is not hard for me to understand why violence so often flairs around election time in Kenya and other African nations.  The level of frustration must be gigantic among the people!  Unemployment, according to Elly, is a staggering 65%!  There are just no jobs for so many men and women, and the level of poverty, the lack of quality healthcare and high level of health risks and disease (do I need to bring up HIV/AIDS?), the violent crime, the cost of education, and more...all this is a heavy burden for the people to endure.  And through it all these people manage to carry on with a magnificent spirit and, almost without exception, a lightless of heart and genuine kindness to all who visit.\r\n\r\n<p>There are supposed to be elections scheduled later this year in Kenya.  Moi has announced that he is stepping down.  This is such an unbelievably beautiful country with many extraordinarily resilient and determined people within it.  I commented to Elly about the poverty here, and he was quick to say, â€œKenya is not poor.â€  No, not in potential itâ€™s not...not at all, and not in spirit.  But in reality the lives of many are hard...so hard!  I asked several people about how they felt regarding the upcoming elections, and almost unanimously they expressed hope that things would change for the better.  We can only hope so, and that better days are ahead for the people of Kenya.  They deserve better, don\\\'t you think?\r\n\r\n<p>Kwaheri</p>'),(2539,'barely any light</br>\r\nbarely any light to see</br>\r\nwinds foreshadowing clash</br>\r\nwinds blowing against</br>\r\nagainst</br>\r\nagainst\r\n<p>\r\nsit and look at me</br>\r\nsit and don\\\'t speak</br>\r\nwrapped in white sheets</br>\r\ndon\\\'t get up and leave</br>\r\nplease</br>\r\nplease</br>\r\n<p>\r\na scream</br>\r\nis that you I see?</br>\r\nlights</br>\r\ncamera</br>\r\na scene that repeats\r\n<p>\r\nuntil you speak</br>\r\nthere\\\'s barely any light to see\r\n'),(2540,'<p>\r\nlets talk about nuclear weapons. we have them. they dont. we use them. they dont. we win. they die. we cheer. they cry. \r\n</p>\r\n<p>\r\nlibya, syria, iraq, iran, china, russia, n.korea. lets bomb the fuck out of them. lets kill the killers. lets show the world whose boss and make it clear to them that we will win. the propaganda war isnt of much concern when the enemy is dead, or slowly dying of cancerous boils. no one talks back if their skin is hanging off their bones. lets get rid of the leaders, their supporters and those in between. \r\n</p>\r\n<p>\r\nif the p.r war isnt making them think they can trust us, then lets show them they cant.\r\n</p>\r\n<p>\r\nwe will continue to prop up the ones who like us, topple the ones that dont. \r\n</p>\r\n<p>\r\nthere are wars that are too hard to fight, and using nuclear weapons would provide us with an easy answer. \r\n</p>\r\n<p>\r\nall of those brave, heroic, u.s soldiers who died maintaining the high tech u.s military overseas. we read about a helicopter crash here and there. a plane down. a fighter missing the air craft carrier deck. lets just bomb the fuckers, all of them, and prevent any more heart ache felt by all those loved ones of soldiers dying of friendly fire and self inflicted mishaps. \r\n</p>\r\n'),(2542,'<p>\r\n1 - Hospital<br>\r\nMy grandmother died in hospital. That was bad, first because the docs fucked up at some point and gave her something she was allergic to; the time they took to realize this didn\\\'t help. Second, because one cannot visit people in hospital all day long. The family has to come and go. Therefore, when one dies in hospital, it often means one dies alone, or worse, with a bunch of doctors and nurses causing them useless trouble. That must be why I hope I won\\\'t die in hospital, like this native American old man I saw the other day in a bad TV series. I don\\\'t know if I will be allowed to die without \\\"intensive care\\\". These days it seems stupidly difficult.\r\n</p><p>\r\n2 - She died<br>\r\nI saw her during her last day. She died the night after that. I thought, as I was on my way, \\\"this is maybe the last time I can see her\\\". I don\\\'t think I was worried, or really sad. I was unnaturally relaxed and receptive. Strong emotions are not let loose in me. I entered in her room, and walked to her bed. I think I put my hand on hers. She opened her eyes. She looked really tired, maybe just from the drugs they were giving her. She said:<br>\r\n- Excuse-moi, petit.<br>\r\nI am sorry, child. I don\\\'t know why she was sorry. I didn\\\'t ask. At that time, I thought she meant \\\"Excuse me because I am not able to talk with you now, I am so tired\\\". Or \\\"I am sorry to make you come to the hospital and worry for me\\\". I thought that way because she was not looking conscious enough to realize she might be going. Now I don\\\'t know anymore. She might have known. She might in deed have told me to forgive her for going. She always cared for us.\r\n</p><p>\r\n3 - My last words<br>\r\nAnd that\\\'s thanks to my wonderful high emotion filter that I could, instead of bursting into tears, tell her something and walk away. I said:<br>\r\n- Take it easy.<br>\r\nI said it in English... to my French speaking grandmother dying. For sure she did not understand. Why did I do that? I think what I wanted to say is \\\"don\\\'t worry, you are just going to die\\\". And I could not. And this was the only \\\"nice\\\" thing to say that my fucking brain could come up with. So it came out encrypted.\r\nNow the funny thing is that I didn\\\'t know at that time the exact meaning of \\\"take it easy\\\". And I still don\\\'t know now, not for sure. I am scared to learn that meaning. Every time people tell this sentence to me, like H\\\'s father before we went back to the US, I am having paranoid threads of thoughts. \\\"Is something really bad happening? What did he really mean? ...\\\"\r\n</p><p>\r\n4 - A good lesson from my former step mother<br>\r\nMy former step mother lost her father and her older brother in a row. There are many things she told me that were worth crap, but on the death-of-someone-you-love chapter, she deserved respect. She said:<br>\r\n- Whatever you do, whatever you say, when you lose someone you always blame something on yourself. So try to enjoy life with the people around you while they are here, but if they die, forgive yourself, because it\\\'s the best thing to do.<br>\r\nHere it is. Now, I don\\\'t think that I needed this advice so badly. I had to learn to forgive myself - and everybody in the bargain - during other adventures. But I noticed I thought many times about when my grandmother was alive, I thought many times that I should have spent more time with her. That\\\'s right, I should have, but I still have many nice memories of her, and I sometimes find myself visiting one of these memories, from the time when I was a kid, and she was alive. Do you want one?\r\n</p><p>\r\n5 - A memory<br><IMG align=\\\"right\\\" SRC=\\\"http://www.swinney.org/journals/images/2542_1.jpeg\\\">\r\nMy step brothers Jeremy and Gilles were 12 and 9 years old, I think. They were fishing on the pier down my grandmother\\\'s house. I was reading or laying in the end of the day\\\'s warm summer sun. She came to bring us snacks. I guess the kids were too busy with their fishing to come to her house and get something to eat like they used to do, like I used to do too when I was their age. As she was staying here with us, talking about easy things, the kids were keeping on fishing. Gilles, the youngest, threw his line wrongly. My grandmother shouted with pain. The hook had caught in the skin of her arm, just above the elbow. We all examined the wound; it was OK since the hook was very small, but its head was inside the skin, and it wouldn\\\'t come out easily. Jeremy and I were making mean remarks to Gilles about his clumsiness. She told us she was fine, there was no reason to get nervous about this. She let me try to remove the hook. This damn thing was not going out, and I was so scared to hurt her. Her skin was like thin parchment. I always hated to remove hooks from fish\\\'s jaw, and this was worse. She was so brave, she was not complaining at all, I kept on asking her every ten seconds:<br>\r\n- do I hurt you?<br>\r\n- no, just a bit.<br>\r\nEventually I had to give up. She went to a doctor to remove it. She never complained.\r\n</p>\r\n'),(2543,'we ended up making several trips back to the site after we found the caves. after all, there was a lot we could salvage from it. usually they\\\'d come with us, and find uses for things we\\\'d never have thought to bring back. \r\n<p>\r\nthe radio was shot, but one of them did find a great use for the parts inside. i guess since i know nothing about electronics it shouldn\\\'t have come as a big surprise that i wouldn\\\'t have thought to scavenge it.\r\n<p>\r\none trip back from the site revealed something about our hosts. every time we actually went, it was always nearing dusk. this particular trip was extended and we spent most of the night there scrounging for anything we could deem useful. we didn\\\'t have any lights of any sort; no flashlights or torches. at first this didn\\\'t seem so strange since there was a full moon above us lighting our surroundings.\r\n<p>\r\nthis particular night we arrived later than we normally would and spent longer there than we normal would have. after finding various detritus that somehow we deemed to be of some arcane use we began to head back. our trek across the desert would take several hours but during the night\\\'s cool it was not too uncomfortable.\r\n<p>\r\nbut the closer to dawn it became, the more agitated our guides became. the lighter the sky became the more anxious they did. it was as if the sun were some bane that they must avoid at all cost.'),(2544,'<p>On day five of our safari we drove through the Central Highlands of Kenya, an area east of the Rift Valley at higher elevation and surrounding Mt. Kenya, which at 5199 meters (14, 200 feet), is the second highest peak in Africa.  Its magestic presence, when not obscured by clouds, is quite imposing.  This region is extremely fertile, and was once known as the â€œWhite Highlandsâ€, as the Colonial Government encouraged European settlers to take up residence there and develop a strong agricultural economy.  Maize, sisal and especially coffee were of great importance, as was the raising of livestock.  The British were optimistic about building a base there for export and invested heavily in the necessary infrastructure.  At the same time, they banned the growing and selling of coffee by locals in order to ensure the availability of cheap labor for their farms and plantations.  All this would eventually be of great importance, both economically and politically.  \r\n\r\n<p>The primary people of the Highlands were and are the Kikuyu, the largest of 42 tribes in Kenya, comprising about 21% of the population.  They are excellent farmers, and because land was the dominant social, political, religious and economic factor in their lives, and since land became the central issue in the struggle for self-rule, the Kikuyu were also in the vanguard of the independance movement.  They were a major driving force, along with the Luo (the second largest tribe), in developing a political community in opposition to colonial rule, and consequently were heavily suppressed by the British, particularly in reaction to the Kikuyu-based Mau Mau rebellion in the 50â€™s (over 20,000 were placed in detention camps and many thousands were killed).  The first president of Kenya, Jomo Kenyatta, was Kikuyu.  Even now Kikuyu are very prominent in Kenyaâ€™s business, commercial and political activities. Come to Africa Safaris Ltd., our safari providers, one of the few African-owned safari companies in the country, is Kikuyu owned.\r\n\r\n<p>Along the way we stopped at Thomsonâ€™s Falls, a cascade of 75 meters, which I cannot recommend going out of your way for.  It just did not impress us that much, and the barrage of people harrassing you to take their picture for money or to buy souvenirs from them makes the stop there less than relaxing, in my opinion.  But Heide has insisted that I point out that it was at Thomsonâ€™s Falls that she had her most touching personal experience of the trip with an animal.  And what was this animal?  â€œSuliâ€.  Suli was the pet chameleon of an enterprising local man who had found and adopted this adorable creature and discovered that there are certain people who absolutely cannot resist fondling it.  In fact, they will pay $2 to do this....just to let it walk on their arm and to photograph it.  I must admit, I was nearly as taken with the cute little fella as she was.  \r\n\r\n<p>Eventually we arrived at Samburu/Buffalo Springs National Park, 85 km north of Mt. Kenya.  Actually two adjoining parks that lie in a lowland area which is fairly hot and arid, it was hauntingly reminiscent for me of the southwestern United.States, especially the so-called â€œhigh desertâ€ area in central Arizona.  The two sides of the park are divided by the Ewaso Nyiro River, and entering the park our first night just before dusk we got a brief glimpse of a leopard sneaking through the undergrowth along the river looking for the ideal spot to lie in ambush.  It was not far from there that we camped, smack dab in the middle of the park, which you will later discover made our time in Samburu even more interesting..\r\n\r\n<p>Samburu is not as densely populated with animals as Masai Mara or Lake Nakuru, but there arenâ€™t as many visitors and vehicles there either.  Here we saw different varieties of both zebras and ostriches than previously.  This was also our first view of the handsome oryx, a large antelope with very long, straight and heavily ridged, spiral horns, along with unusual black markings on its face and body.  Also of interest was the gerenuk, a much smaller antelope that is commonly seen browsing from bushes on its hind legs...quite an odd sight!  Are the leaves at the top of the bushes that much tastier?  And then thereâ€™s the diminutive dik-dik, an antelope that stands only about 40cm (15 inches) high, so tiny and cute that it seems better suited to a peaceful Zen garden than to these treacherous surroundings.\r\n\r\n<p>What we especially enjoyed watching were the baboons, which congregate in large groups, sometimes dozens at a time, and which are great fun to watch because they are always busy doing something...always...and it seemed as though each baboon was doing something entirely different.  Usually on the ground, but occasionally in trees as well, they are constantly in motion: running, itching, eating, playing, squabbling, climbing, jumping and also screwing.\r\n\r\n<p>So far I havenâ€™t really shared that much about the birdlife in the parks, but they are diverse and also incredibly beautiful: the secretary birds, the varities of guinea fowl, the eagles, hawks, hornbills, herons, egrets, hammerkops, cormorants, storks, vultures, crowned cranes, and one of my favorites, the small and aptly named â€œsuperb starlingsâ€, which often frequented our camp looking for handouts.  These are just a few...Kenya has over 1200 species.  The bird with my favorite name is the white-billed bastard.\r\n\r\n<p>Our campsite had a simple latrine (outhouse), a nearby faucet for washing up, of course our tents, and the â€œkitchenâ€, a simple but effective setup where our cook Peter worked his magic.  The best food by far that we had in Kenya was at our campsites, courtesy of our appointed cooks. Each meal was carefully and deliciously prepared, proudly presented, and voraciously consumed.  The cookâ€™s job was also to guard the camp in our absense against mauranders, especially baboons.  We were advised not to leave our footwear outside our tent at night, or at any other time for that matter, as it would surely be stolen.  From the sound of it the baboons probably have a cache of shoes that rivals Imelda Marcos!\r\n\r\n<p>Our first evening at the Samburu campsite, Heide had an unsettling surprise as she was sorting through her stuff in the tent...a scorpion!  It had rudely invited itself in as we had apparantly been remiss in zipping up soon enough after stowing our gear.  Having lived and backpacked in Arizona for 18 years scorpions were no big deal to me, but this was her first introduction to one and she was not at all pleased to meet it!  Elly quickly stepped on it....crunch.\r\n\r\n<p>At night after dinner I would sit around the fire, sip a local beer (Tusker, Safari or Kilimanjaro), and talk with our driver, cook and campsite helpers.  These are men who are often separated from their families more than theyâ€™re with them in order to provide for them.  These conversations afforded me an invaluable opportunity to gain a still deeper insight into a people for whom tradition and family life are important, who are proud yet humble, and who are patient and enduring through all the difficulties they face â€“ still quick to smile and laugh.  When prompted, they had loads of â€œyarns to spinâ€, and eagerly did so...so many priceless stories they shared.  Later before turning in there was time to peacefully gaze at the luminously clear sky, stars glittering, and to listen to the choir of cicadas and the hyenas and elephants fill the still-warm evening air with their symphony.\r\n\r\n<p>Have you ever had to get up in the middle of the night to pee?  You too, huh?  When camping?  Yeah, me also.  That night I stumbled out of the tent and into the nearby bushes and was taking care of business when a huge beam of light spotlighted me like I was center stage at Carnegie Hall.  Imagine my surprise.  No worries...just a ranger patrolling the grounds - standard procedure.  The next morning at breakfast Peter informed us that an elephant had come through the grounds during the night.  When I asked him if this happens often, he shared that on one recent occasion an elephant had paid a visit and decided to rearrange the campsite a little.  â€œA tarpaulin was blocking its way so it ripped it down!â€  Urban renewal...African style.  I asked him what he had done when the elephant arrived.  â€œI ran!â€, he confessed.  That very moment I solemnly vowed from that point onwards to significantly restrict my intact of fluids during the evening!  \r\n\r\n<p>The river running through the park created special opportunities for viewing game, since in that desert-like environment itâ€™s essential for all the wildlife to make periodic visits there.  From our vantage points perched along its bank, we observed herds of elephants drink their fill and cool themselves off, spraying water and covering themselves with mud like little children.  But itâ€™s not quite as convenient or fun for the giraffes to drink.  They must awkwardly spread their front legs to reach the water, which puts them in a highly vulnerable position to attack from either lions or leopards.  So they would look, look, look, and then take a drink....then look, look, look, and then take another...and so on.  Grevyâ€™s zebras also trotted up to drink, glancing around nervously, their tails constantly swatting the everpresent flies.  \r\n\r\n<p>Late our second afternoon in Samburu we drove around for quite some time, back and forth along the haphazard grid of dirt roads that weave their way through the park, seldom spotting any game.  But it mattered little as I became capitivated by the intricate richness of the landscape: the rich tapestry of subtle colors, and dramatic contrast of gigantic trees and miniscule cacti and flowers.  A gentle and much welcomed breeze stirred the carpet of thick yellowing grass, various kinds of birds and lizards scurried here and there across the dusty red road and into the dense scrub, and above it all soared a vast vista of dark rolling hills and a vividly blue sky punctuated by puffy white clouds.  Occasionally a dust devil swirled madly and was soon extinguished.  I was reminded again of what Hemingway wrote while here, â€œNothing I have ever read has given me any idea of the beauty of the country.â€.  Amen!\r\n\r\n<p>Eventually we stopped to watch a family of baboons...entertaining as always.  Then remarkably, Elly somehow spotted a leopard crouched down in the bushes.  He pointed, â€œItâ€™s right over there!â€, and Heide and I searched and searched and searched for it but just could not find it anywhere amongst the tangle of grass, trees and brush.  This went on for nearly ten minutes, and I thought my eyes would pop out of my head as I peered out so intensely, so desperately wanting to see it.  But eventually it stepped out into the open only about three meters away from us, and then slowly walked directly in front of our van and into another bush.  There the leopard remained hidden, hoping impalas or gazelles would unsuspectingly stroll by.  We could barely see the top of its head just above the grass.  It waited...and we waited...patiently.\r\n\r\n<p>Suddenly one of the baboons realized that the leopard was there, and a big male strutted up to within a couple of meters of where it was lying, puffed out its chest and chattered out an angry warning as if to say, â€œBack off Jack!â€.  Iâ€™m thinking, â€œThis is the mighty leopard itâ€™s challenging.  Does this baboon have a death wish?â€.  But what amazed us both was that the leopard instantly backed off, dropping down completely out of sight.  I asked Elly about this and he surprised us with the fact that a leopard will not mess with a baboon, a tremendously strong and fierce animal with massive teeth.  This is no cuddly chimp we talking about here folks...this is a one bad motherfucker!\r\n\r\n<p>After two nights at Samburu we were off to Amboseli National Park, which demanded a full day of bone-jarring, teeth-rattling traveling, occasionally passing scattered towns and villages, as well as farms and plantations, the larger of which are still foreign-owned.  Each of the communities had a similiar appearance: dusty pot-holed streets; single-storied, tattered-looking stores and shops with shaded arcades; lines of make-shift stalls filled with bananas, mangos, papayas and other freshly-picked fruit; and always several ramshackle buildings with hand-written lettering in white paint.scrawled on their bleak facades advertising â€œHotelâ€.  Frighteningly shabby-looking from afar, I could only imagine what a room inside was like and shuddered at the very thought of actually spending a night in any of them for a night.  Outside on the streets people were everywhere either busy with their daily routines, or else just standing or sitting around.  Where we were in Africa there were always huge numbers of people almost everywhere, just standing or sitting around, seemingly doing nothing.\r\n\r\n<p>There are two reasons why most people come to Amboseli.  The first is the Big K. â€“ Mt. Kilimanjaro...the mother of all mountains in Africa...its highest...magnificent and legendary.  Hemingway waxed poetic about it, â€œAs wide as all the world.â€.  Millions upon countless millions have photographed it.  A good many travelers to Africa have puked their guts out trying to climb it.  Yours truly has lusted over it since I was an adolescent leafing through National Geographic and Outdoor Life magazines.\r\n\r\n<p>The second reason is the elephants.  We saw lots of other animals there, many of the ones I have mentioned already, but the main memories I have from Amboseli regarding the wildlife are of its extraordinary elephants.  Granted, there are elephants in many parks and reserves in East Africa, but those in Amboseli are extra special.  First of all, they are generally the largest you are likely to see anywhere, with probably the largest tusks of any as well.  Why?  Even though much of the park is semi-arid, there is a significant marshy area that results from run-off from the snows of  Kilimanjaro.  So even during the dry season when other parks and reserves offer slim pickings for grazing, there is an abundance of food in Amoseli for all the grass-eaters.  An elephant will consume as much as 275 kg (600 lbs) of food per day, and here itâ€™s Fat City year-round.  They get really huge...over six tons!  And the tusks?  I saw a few bulls with tusks that nearly reached the ground...some must have been as much as two meters long.  And there are a lot of elephants there.  At one point we parked the van and looked out at approximately 200 of them milling around, mostly eating of course.  Thatâ€™s a sight you wonâ€™t easily forget.\r\n\r\n<p>It was at Amboseli that I saw what was the funniest thing that any animal did on our safaris.  It had to do with a wildebeest (gnu), which should be of no surprise to those familar with the wildlife there.  Now the wildebeest is a strange animal to start with.  First of all, it is generally acknowledged by most everyone to be the stupidest animal in all of Africa, a dubious distinction to be sure.  Their behavior is certainly eccentric to say the least.  They can be observed in their herds snorting, tossing and shaking their heads, bucking for no apparant reason, and running around in circles like complete idiots.  \r\n\r\n<p>In their annual migration, which runs from July to October, and which apparantly is an absolutely staggering spectacle to behold, countless numbers of wildebeest thunder from one end of the Serengeti Plains to the other in search of greener pastures.  Now get this.  When they come to a river, they act like theyâ€™ve never seen one before!  They will stand around looking at it, and looking at each other, as if wondering what to do next.  Eventually one of them will boldly decide to take the plunge...literally.  And then they will all wildly lurch in, one after another, diving on to rocks and on to each other so recklessly that huge numbers will perish from killing either themselves or each other in their haste and stupidity.  Naturally the crocodiles just love this.  All they need to do is just lie in the river, wait for carcasses to drift by, and then gorge themselves to their heartâ€™s content.  When we were there, the ranger at the hippo pool in Mara told us that so many wildebeest perish at that river crossing that sometimes the stench of death is so bad you canâ€™t get anywhere near the water without practically barfing.  \r\n\r\n<p>Well, in addition to not being such a bright animal, the wildebeest just might also be the ugliest creature in all of Africa, though the warthog and the hyena would surely rack up a fair number of votes in that category as well.\r\n\r\n<p>But on top of that, Iâ€™m suggesting that this animal might also be the most cowardly of them all.  Hereâ€™s why.  In Amboseli, we were watching a pair of crowned cranes, a magnificent bird with jazzy yellow crests on its head, that is fairly common in the parks and reserves.  With them was their tiny, tiny chick we could barely see in the grass.  Well here comes a wildebeest all by its lonesome, which isnâ€™t so smart in and of itself considering that this makes it easy pickings for a even a half-blind, half-lame, senile lion.  But anyway, as it ambles along towards the cranes, they decide that heâ€™s getting just too close for comfort to their precious offspring, so one them spreads its wings out fully to a diameter of about a meter and a half.  You would have thought that the wildebeest had just barreled into a high-powered electric fence, as it jumped back a good meter and raced off in terror with its tail between its legs.  You could almost hear the cranes laughing their tail feathers off.\r\n\r\n<p>When I think about all this, and then see how many wildebeest are still around, it makes me question a little Darwinâ€™s theory of  â€œthe survival of the fittestâ€.  In this case maybe itâ€™s â€œthe survival of the stupidestâ€.\r\n\r\n<p>As we drove through Amboseli Park the clouds began to tantilizingly lift off of Kilimanjaro, just ever so slowly.  In time we could see patches of snow here and there.  Then more.  And then finally the full summit was in view and I could not take my eyes off of it.  I was totally spellbound!  The tears rolled down my cheeks as I felt the fulfillment of a life-long yearning.  Being here and seeing this mountain, for me, represented the culmination of so many years of longing, years of hoping, years of saying to myself, â€œSome day I must and will see Kilimanjaro!â€.  Taking it all in embodied all that Africa had ever meant to me, all I ever wanted to know about it, and all that I had experienced on this trip.  All those thoughts and feelings rushed through me like a cyclone.  I wiped away the tears, and more came, and I turned and said to Heide, â€œThis is one of the happiest days of my life.â€   And I really meant it!\r\n\r\n<p>I will have more to say at another time about Swahili, the common language of East Africa, but for now I will share with you just one word: â€œbarakaâ€.  Like so many other words in Swahili, it has a beautiful sound to it.  But I think the meaning is even more beautiful: â€œblessingâ€.  Gazing out at this magical mountain I felt a deep, deep sense of priviledge and gratitude, and knew that I was embracing a joyful baraka.</p>\r\n\r\nKwaheri,'),(2545,'<p>it\\\'s very late and i could wish for nothing more than to be one of the two cats curled up on the couch at my feet. oscar is stretched out on his back, his hind legs spread eagle and his front paws up over his eyes as if annoyed by the computer-screen glare (damn, woman, he must be thinking, why won\\\'t you go to sleep already?). uno, the baby one, is snuggled up into the curvy part between oscar\\\'s head and chest. he\\\'s licking his tiny paws. they\\\'ve been at it for hours. earlier they were on the bed. just lounging there, licking each other vigorously. happily. sometimes oscar\\\'s tail will flap up, startling uno into chasing it like he would a mosquito eater or one of those toy mice. it\\\'s so cute it\\\'s hard to watch (but don\\\'t worry, we have pictures that da will upload for you later).</p> \r\n<p> i found oscar while searching for my friend margaret\\\'s cat, kwan, who she lost while on her honeymoon. she made the mistake of leaving kwan with our friend holly, a smoker, in her second-story apartment. kwan took her chance for escape when holly irresponsibly took a bathroom break in the middle of an opened-window smoke break. </p>\r\nmargaret, upon her return, was homeless, (another story) so she asked me to use my number on the kwan fliers (which were complete with her own hand renderings). one of the first calls we got sounded so promising. alas, it was not kwan. but it was a kitty who came right up to me, hopped in my arms, nuzzled up to my neck and promptly began licking it. i kept him. margaret wept. </p>\r\n<p> [short sidenote: margaret\\\'s misery made it impossible for me to keep this cat without trying to find its doubtless desperate owner. i tracked her down through the animal shelter, but she was so incredibly flaky that when she came to get him and i told her i thought her cat was really neat she said i should just keep him. swear to god.]</p>\r\n<p> margaret, meanwhile, refused to give up. i helped her search for weeks. we scoured the neighborhood and went to the county animal shelter countless times. she even went to dinner with an old russian couple she encountered on one of our door-to-door trips. everyone thought margaret was insane. it had been more than one month. that cat was long gone, they told her.</p>\r\n<p>then, one random evening as i was attempting to serve pasta to four people with only two forks, my phone rang. someone had found a cat underneath a porch next-door to holly\\\'s apartment. they happened to have kept one of the fliers magneted to the refrigerator, for all that time. when we saw kwan--tiny and mangled--we couldn\\\'t even recognize her. she weighed 18 pounds when margaret went on her honeymoon. that night at the vet, she weighed nine. the cat survived, though she went through a rough period of looking as though holding her own head up was the hardest thing she ever had to do. margaret went for a couple of weeks wondering whether it really was kwan. but one morning, the mangled cat hobbled over to her bed and did the trademark kwan move to say get your ass up and feed me: one paw on one eye, wet cat nose on the other. </p>\r\n<p> that\\\'s the thing about cats, i have found. they have amazing stories.</p>'),(2546,'i tell the most important things<br>\r\nto strangers and chew my lips<br>\r\nin front of those i love; forgetting<br>\r\nthe motion of tongue and teeth and mouth<br>\r\nis the perfect concerto because<br>\r\nsilence can cover everything<br>\r\nugly.<br>\r\n<br><br>\r\nthe pull of quiet is like my winter<br>\r\nblanket. and indeed, isn\\\'t snow a blessing?<br> \r\n<br><br>\r\nonly when spring comes, laughing<br>\r\nÂ Â   like a girl, and pulls off the snow,<br>\r\nÂ Â   shows you the candy wrappers and<br>\r\nÂ Â   the garbage and the dirty brown grass<br>\r\nÂ Â   that the white purified, can you<br>\r\nÂ Â   see how blissful it was to have all this<br>\r\nÂ Â   ice to skate over.<br>\r\n<br><br>\r\nwhy don\\\'t we close our eyes<br>\r\nand use our mouths<br>\r\ndifferently.<br>'),(2547,'I thought I went home because I needed some time off from my life. It was meant to be a summer of isolation and productivity. Just me and my laptop and of course the beach. But as most things tend to do it ended up being about something else entirely.\r\n<p>\r\nMy parents have a cottage in Northern Michigan in a little town with one main street complete with the grocery store, post office, bank, ice cream shop and the hardware store (which has been empty for several years now). Our cottage was on the street behind Main street right next door to my grandparents\'.  The town has a beach on Lake Michigan and it is to me the magical place of child hood memories: fresh air, cold water, hot sand, dark nights, paint-by-numbers in the rain, and grandma\'s lap. \r\n<p>\r\nMy family showed love through no-mercy-teasing but no one could breach the sanctity of grandma\'s lap. It was the one place I was safe, while nuzzling my head under her drooping neck and inhaling the acrid smell of old tobacco I would cower while she dismissed whoever had been my harasser with a \"now you just leave her be.\" It was unconditional love that I wore like a shield while flashing eyes back at my brother or aunt or uncle or even father that said \"see grandma thinks you\'re mean too!\"\r\n<p>\r\nShe was the archetypal perfect grandmother with the special spaghetti sauce and loving embrace. \r\n<p>\r\nThis summer she was old. She quit smoking about five years before she was diagnosed with lung cancer. It was a huge slow growing tumor when they finally found it. That was about five years ago. The chemo beat down the cancer, but it left my grandma a much older frailer woman. Her feet and hands were numb and her back bent like a question mark. The whole family noted a change in her attitude. She was no longer looking on the bright side, but neither would I if I had gone through the sudden decline in health she had.  It only seemed fair that she got to be a bit of a bitch at times. But with grandpa\'s help she made her famous spaghetti sauce to welcome me home. I was still her little princess even if these days her lap had lost its plushness and would have snapped under my weight. \r\n<p>\r\nIt was just an added bonus that I would get to see my grandparents when I decided to spend a month of summer up at the cottage trying to clean my head out and pour some of it onto a page. \r\n<p>\r\nI took my grandma for a walk every morning. I would stumble, still half asleep, next door at 9:30 in the morning for our daily ritual. The necessities were gathered: a hat to keep the sun out of her eyes (hows my hair, is it sticking out?, she says), a cloth bag containing some tissue for running noses, paper towel for wet benches, the combination to the post office box, and two quarters, as well as Michigan State cushion for the hard bench surface.  I was to inform her of the weather from the ten seconds I had spent outside on the walk over and if necessary to help her on with an extra sweater. \r\n<p>\r\nThen the walk. She had a cane in one hand and me in the other. Our forearms intertwined, hands clasped and her elbow securely tucked into my body just over my hip bone. And we walked. Slowly. Small slow steps. Down the alley behind the grocery store where on Tuesdays the kids would be unloading and pricing the stock for the store, stopping at the front of the store to get one copy of the Detroit Free Press (check the date, she says). On across the street by the post office, but we can\'t stop there now, they won\'t be done sorting the mail yet. Turn left onto the road down to the beach (after all these years I still don\'t know what its name is). Then half-way down the hill to rest on the bench. On the bench we watch for bunnies and birds playing in the marsh of the little lake and watch the horizon out on the big lake for boats. We talk a little. \r\n<p>\r\n\"California is so far away. And I will miss you when go back, but I know you like it there so I will just think about that,\" she says as the boat moves slowly on the horizon.\r\n<p>\r\nAnother day:\r\n\"Even with all the bad stuff, the running nose, the aching legs and back, I am glad I did it. I would rather be here than not be here,\" she says as the bunny disappears into the cattails.\r\n<p>\r\nThen its time after the stalling, the waiting for one more bunny or that ever allusive deer, time to walk back up the hill across the street and rest again on the bench by the post office. I would leave her there and go in and check the boxes with their ancient dial combinations that I could never remember. \r\n<p>\r\nThen back to home where grandpa was usually waiting having just returned from his morning golf unless he was still at the dirty old men\'s club having a beer.\r\n<p>\r\nWhen I left to return to my life I know it made her sad. She said she would think about how happy I was, but everyone told me how sad she was. How special they thought that month I had with her was. They told me that at the hospital a week later when I returned because she was dying.\r\n<p>\r\nWe all knew she was not strong, but no one knew how bad it was. She never told us. Never told anyone that the doctor had informed her that one of her lungs was completely damaged, that for two years she had only one lung. She was not going to get better this time. The family decided to take her off the respirator.\r\n<p>\r\nWe were all there. Her husband, five children, one daughter in-law, three grandchilden, one grand-daughter-in-law, and one grandson. We all said good-bye in what ever way we could. And waited for the morphine to arrive to make her last breathes easier. \r\n'),(2548,'<p>hi, Im trying to get someone on the planet earth to contact austin swinney to let him know that I am almost positive his flight to thailand to see MOI is leaving tonight at midnight. I think 12AM on march 20 is tongiht, am I right?? I asked the girls here at the internet cafe and they said yes. I know that some of you on this web site have austin swinney\\\'s phone number and could call him up and tell him what I\\\'m saying to you now. I think he is speeding somewhere on route 1 just screaming Eminem songs out the window into the night wind without a care in the world, but I would really like to see him, so if one of you fine Swinney readers would take it upon yourself to do this, I would be so grateful.</p>'),(2549,'i started to write something about swinney dot org a few minutes ago. it turned into this rant about how i have had a hard time writing lately, and also an aside about a test i had today where i had to write two essays. it had a lot of adverbs, and i have been reading Hemingway lately and he made me think about how bad adverbs can be. they are just a weak thing to use in 99% of all writing scenarios. check it out.\r\n<p>\r\n<i>John quickly extinguished the candle.\r\n<br>John licked his fingers, and pinched out the candle before the snipers could get his range.</i>\r\n<p>\r\nsee? taking away the adverb makes you write more and helps distract you long enough to <i>really</i> develop your ideas, or maybe develop your ideas <i>beyond the point at which you normally lose interest in what you are talking about</i>. thanks ernest.\r\n<p>\r\nthis is twice tonight that i have tried to write something about swinney dot org, and i still have this half-idea floating around my head about why i want to submit things here, some deep soul searching monologue on audiences and loneliness and friendship and the nature of human interaction, but i don\\\'t think that\\\'s going to work tonight. \r\n<p>\r\ni am supposed to write a story for friday that includes a magical element, it can be anything, that the story hinges on. my ideas so far are a magic typewriter that lets this guy crank out masterpieces of literature, and a magic guitar pick that, you guessed it, lets this guy play like a rock star. i am a predictable man. but--i am going to try to write it so it isn\\\'t one of those cliche stories where the guy finds out the the magic was <i>inside him the whole time</i>. i haven\\\'t worked that part out yet but if i do it might be a good story.\r\n<p>\r\ni guess by now i should be thinking of a clever way to tie all this up <i>neatly</i>, or should i say tie all this up <i> into an easy-to-swallow well lubricated low-time-investment-on-the-part-of-the-reader package</i>, but nothing\\\'s really coming to me. peace out.\r\n'),(2550,'<p>I live in a cheap apartment. The wind blows right through my windows, my carpet doesnâ€™t reach all the way to the wall on the west side. Lately the hot water only lasts for 4 minutes at a time.</p> \r\n\r\n<p>So I call the landlord everyday. He doesnâ€™t have an answering machine. Usually his wife answers and I leave a message. English isnâ€™t her first language, and I know she isnâ€™t writing things down. What the fuck does she care? She probably gets a hot shower everyday. Yesterday when I called the landlord answered so I started to talk to him. â€œNo no! Heâ€™s not here! Be back in one hour!â€ he says. My eyes roll up in my head and the steam builds up ready to come out of my ears. â€œOhhhKaaayyyâ€¦â€ I say and slam the phone. He knows why Iâ€™m calling. I call everyday. I want a hot fucking shower just like his wife.</p>\r\n\r\n<p>He calls me this morning at 9am. He says that a Plumber Man is coming. Iâ€™m asleep and skeptical, â€œOhhhKaaayyyâ€¦â€ I say again and hang up. But 45 minutes later there is a Plumber Man in the basement with the landlord. I see the truck out front and I can hear their voices coming up through the airshaft. Heâ€™s talking about steam boilers and making metal on metal sounds with some kind of tool. I went down to hover and see what I could see. </p>\r\n\r\n<p>The boiler is a little old 40s number, kind of like the ones that turn into monsters in movies. When I go down there the old man in the building next door is playing hymns on the organ again. The sound carries really well through the airshaft. This haunting melodic sound track. Itâ€™s creepy. It\\\'s the perfect music for ancient boiler repair. The Plumber Man says he can fix it. Heâ€™s a younger plumber, physically fit and his shirt is tucked in so you donâ€™t get that crack effect. He looks to be taking the job seriously. Heâ€™s clanging pipes and flushing connections, cleaning screens. The landlord says â€œThis is the tenant.â€ Like Iâ€™m the only person in the building whoâ€™s noticed thereâ€™s no hot water. He asks the Plumber Man if he needs to see my apartment. Why would he need to see my shower? The boiler is fucked up, not the shower. When I tell him my hot water lasts 4 minutes, he laughs, â€œHa ha!â€ (the landlord winces) and says, \\\"IF THAT!\\\" Apparently, the boiler is not filling up all the way. It also has not been cleaned in decades, so I think about the slimy shitty gunk that is coming up the pipes to my shower. Maybe I havenâ€™t been cleaned in a while either. He says, â€œIâ€™ll have you all fixed up! Donâ€™t you worry!â€ But I worry. He doesnâ€™t know my landlord. He doesnâ€™t know Iâ€™ve havenâ€™t had decent hot water action since I showed up in 1996.</p>\r\n\r\n<p>You probably get it by now that having adequate hot water will be kind of life changing for me. I think about it all the time. I was coming over the bridge from Oakland on Sunday thinking to myself, \\\"You know, hot water is not a luxury\\\" and dreaming about hot showers, which is probably partly why that night, I fell asleep at a friends house. The thought of one more cold shower in a row was heart wrenching. I was coming over the bridge last night from Berkeley day dreaming about it too. Maybe itâ€™s just seeing all that water in the bay that brings it to mind. I am a person obsessed with the idea of hot showers. Of showers that last more than 4 minutes. I haven\\\'t even dared dream of a hot bath in months.<p> \r\n\r\n<p>I wouldnâ€™t mind washing my dishes once in a while either.</p>\r\n'),(2556,'i pretend to sleep while it drizzles. the rain drops are how i imagine musical notes would look if they had three dimensional bodies: all curvy, full and shimmery. my parents are fighting again, i can hear the scuffle of wrists being caught and snapped, of my mother\\\'s hair tangling, of my father\\\'s animal-sobs, above the sheet metal beat of the rain. <br><br>\r\nbut if i close my eyes i can believe its merely the soundtrack to a tv show i wouldn\\\'t let my siblings watch. my little brother usually hides in his closet while it happens, and sometimes we find him there, asleep, his sneakers the pillow. the louder my parents shout, the more silent we children become. <br><br>\r\nonce i saw my sister creeping into the kitchen, her face lit up and eerie in the electric green light of the microwave clock. she was hiding all our knives and even the vegetable peeler. the blood of our parents\\\' marriage was real, fluid, crimson.<br><br>\r\nthe rain quiets, and all of a sudden, so do my parents. when i sneak downstairs on my tip toes, as softly as possible, not touching the seventh step from the bottom because it creaks, i don\\\'t know which room they are in. \r\n<br><br>\r\nmy mother is on the sofa in the den, muffling her tears with a hand-embroidered cushion. my father is invisible. then i hear the minivan, and resist the urge to look through the front window. only after the engine fades do i walk to the long thin lace-covered pane beside the main door.<br><br>\r\nIt isn\\\'t raining anymore, but drops fall from the canopies at the very tops of trees, the eavestrough, the fire hydrant in front of our house. the rainwashed neighbourhood looks gentle. everything is pale and radiant. everything is at peace.<br><br>\r\n\r\n'),(2551,'<P>alone in my canoe.<BR>close my eyes and i could be in the sea of<BR>marmara<BR>all quiet but for a distant chugging<BR>that we can pretend is a russian tanker<BR>coming through the dardanelles<BR>instead of a shrimp boat navigating the channel.<BR><BR>three bottles of retsina help complete the illusion.<BR>the corks say \"axata clauss\" in faux greek lettering.<BR>pull them out.<BR>lift the mosquito netting<BR>and set them gently on the water.<BR><BR>tied to the dock<BR>sleeping out here tonight<BR>behind the house in bayport.<BR>supposed to watch a guy pour a parking slab tomorrow.<BR>i can\'t sleep alone<BR>inside a house anymore.<BR>that luxury has departed me.<BR>the last time i tried it<BR>i had nightmares wherein<BR>hungry ghosts attacked me<BR>in various desert locations<BR>trying to tap my energy.<BR><BR>stereo inside the house<BR>blaring selections from<BR>the pretenders and roy orbison<BR>the \"mulholland drive\" soundtrack<BR>the audio book of <U>the man who fell to earth</U><BR>prince and steely dan<BR>guided by voices<BR><BR>lloranda<BR>show biz kids<BR>delirious<BR>mystery achievement<BR>in dreams<BR>your gold teeth<BR>under the neptune<BR>when you were mine<BR>crying<BR><BR>smoke an eighth<BR>from my rubber ducky bong<BR>is good shit, mang<BR>but i don\'t feel anything<BR>maybe i\'m saturated<BR><BR>but the stars seem menacing.<BR>they didn\'t before.<BR>may need to quit smoking.<BR>for a little while.<BR><B>after closing<BR>at the guernsey fair<BR>i detect the El Supremo<BR>from the room at the top of the stairs.</B><BR><BR>go inside at midnight and turn off the music.<BR>get an eggplant<BR>and a jar of tuna-stuffed olives<BR>from the fridge.<BR>take them out to the dock<BR>open them up and lay them on the planks<BR>with nine pennies and some horse hairs.<BR>to supplicate oya.<BR>she\'ll keep everything away.<BR><B>a candy colored clown<BR>they call the sandman<BR>tiptoes to my room every night<BR>just to sprinkle stardust<BR>and to whisper:<BR>go to sleep<BR>everything is alright.</B><BR><BR>for me,<BR>these entries feel encoded,<BR>like i\'m just a courier<BR>running to marathon.<BR><BR>maybe we\'re being watched.<BR><BR>the concrete guy wakes me up.<BR>probably thinks i\'m crazy<BR>for sleeping out here behind a house<BR>full of beds.<BR>he\'s one of those<BR>hyperthyroidal types,<BR>eyes bugging out<BR>like they\'re trying to see around the corner<BR>of his head,<BR>and check out his ear.<BR>he\'s a real talker.<BR>the mexican dude with him keeps quiet.<BR>concrete man knows all about concrete<BR>plumbing<BR>cars<BR>women<BR>politics<BR>and the mind of god.<BR>i can see right away<BR>that my function here<BR>is to be designated listener<BR>while the mexican guy<BR>does all the work.<BR>otherwise, concrete man<BR>wouldn\'t have anybody to talk at<BR>besides pedro,<BR>and nothing would get done.<BR><BR>mom calls at lunchtime.<BR>she tells me about some<BR>missionary friends<BR>who are quitting the game.<BR>they traveled so much<BR>they felt like they were<BR>losing their identity.<BR><BR>i\'m getting fat again.<BR>it\'s funny when you\'re big:<BR>you don\'t feel fat,<BR>like there\'s anything extra,<BR>but then you catch yourself<BR>in the mirror<BR>and you can\'t deny it.<BR><BR>sometimes i\'m afraid<BR>i\'m going to disappear.<BR><BR>after all this is over,<BR>if i live til friday,<BR>i\'m going back down to tampa.<BR>stay drunk for a week<BR>and work on my novel.<BR><BR>concrete man wants me<BR>to go into business with him.<BR>i\'d be the office help<BR>and the go-to guy:<BR>doing the books, computer stuff<BR>and estimating.<BR>we would be bankrupt<BR>inside a year.<BR><BR>i\'m taking the train<BR>to new york<BR>for my birthday.<BR>hopefull stay with peter<BR>and<BR> dance<BR>dance<BR>dance<BR>in some cool dark room.<BR>x marks the spot.<BR><BR>i feel like throwing concrete man in the river.<BR>throw half an eggplant<BR>at his big head.<BR>sink the retsina bottles and the canoe.<BR>burn down the house.<BR>suck pedro\'s hot dick,<BR>take my nine cents<BR>and go home.<BR><BR>i want to see<BR>\"y tu mama tambien\"<BR>but it probably won\'t get down here<BR>til may or june.<BR>such is the provincial life.<BR><BR>i\'ve got a journal site now:<BR>machupicchu.diaryland.com<BR>ya\'ll don\'t wear it out looking at it.<BR>(i\'d try to put an href tag in here,<BR>but i\'d probably just fuck it up.)<BR><BR>you droogies have a happy springtime.<BR><B>and that\'s the code for go.</B></P>'),(2552,'<p>driving home from work today it occurred to me: my car is so messy, if i ran off the road into one of the many steep ravines i pass each day, i could survive on its contents relatively happily for weeks.</p>\r\n<p>sustenance:<br>\r\n* stale water in at least four different bottles<br>\r\n* 1/4 bag of jolly rancher jelly beans<br>\r\n* two mini-whatchamacalit bars in glove compartment<br>\r\n* one can of fresca<br>\r\n* 1/2 bag ricola cough drops<br>\r\n* one bottle marjoram spice</p>\r\n<p>entertainment/reading material:<br>\r\n* dozens of cassette tapes, including but not limited to: pavement, liz phair, built to spill, luna, cat power, kleenex girl wonder, u2, bright eyes, how to learn spanish, johnny mathis christmas collection<br>\r\n* l.a. and orange county thomas bros. guide<br>\r\n* various old issues of the l.a. times and time magazine<br>\r\n* a box full of news article clips, greeting cards, notes and misc paperwork belonging to a friend who never retrieved it from my car<br>\r\n* set of 5-pound weights</p>\r\n<p>wardrobe:<br>\r\n* one pair of levis and lime green cotton shirt i had meant to donate to charity but never did<br>\r\n* turquise t-shirt from elementary school i did a story on (colorful dancing bears on back)<br>\r\n* one pair black fuck-me boots<br>\r\n* one pair burgundy raver dancing shoes<br>\r\n* dirty yellow socks<br>\r\n* one pair chunky mary jane sandles</P>\r\n<p>protection from extremeties:<br>\r\n* a warm and yummy sleeping bag still dusty from desert road trip<br>\r\n* yoga mat<br>\r\n* rain jacket with hood<br>\r\n* very ugly umbrella purchased for $2 on streets of new york city<br>\r\n* fancy brown leather gloves i got for christmas. they only ever made it once from house to car<br>\r\n<p>sentimental:<br>\r\n* souvenier given by best gay friend from the <a href=\"http://www.bunboybaker.com/thermometer.htm\">tallest thermometer in the world<a><br>\r\n* ceramic cup from paris hotel in las vegas purchased while visiting same best gay friend</p>\r\n<p>so the question becomes: am i a slob, or simply more prepared than most in the event of a disaster?</p>'),(2553,'<p>\r\ni am at work. i am bored. my boredom is so thick it became difficult to move. if i were a bit less bored, i might be able to enjoy myself by creating something. invent new Dilbert stories for example. but at the point i am now, only a massive slaughter happening right here could make these cubicles get a little bit of fun. if the guy is clever he could cut the throat of two or three persons without anybody noticing. then someone would scream. some would raise their head up to look. some would see and run away. things would go faster. a few would be severely injured instead of deadly. more blood. up in the air, on the ugly ceiling. several sitting not too close would dial 911 at the same time. the police would come in 5 or 10 minutes. one could see their lights flashing on the parking. before being shot, depending of the guy\'s strength, on the weapon he chooses, and on his proficiency, he could reduce the number of boring people working here by 10 or even more.</p><p>\r\n\r\nthen, in just a few days, boredom would be back just as if it never stopped. and, with a great deal of luck, i won\'t be here to see it.\r\n</p>'),(2555,'<p>He looks over at her, exhales and takes a final drag on his cigarette. He sees heâ€™s sucked it down to the filter, and smashes it out in the dirty ashtray in front of him, careful not to burn the discarded rubber band. He thinks a burning rubber band would smell like small burning tires and he doesnâ€™t want to risk having that stink around after he pours another manhattan into his gut. </p>\r\n\r\n<p>Sheâ€™s still sitting next to him, her head listing to one side, her glass held up in front of her mouth. She isnâ€™t drinking from it, sheâ€™s holding it there to hide her smile. The whiskey starts to soften him up around the edges and he starts to think she looks a little like Jackie O. She doesnâ€™t, but thinking about Jackie O makes him feel sentimental. He stares at himself in the mirror behind the bar, thinks about the woman who stood him up earlier. He flicks the ashtray with his finger and the butts roll away and back again.</p>\r\n\r\n<p>She stretches her arm out and lightly puts it back on his forearm, he can barely feel it, but it pulls him back into the present. He watches her gulp down the rest of her drink and then she winks at him, giggles and shakes the ice around in her glass. He doesnâ€™t know what else to do, so he orders two more.</p>\r\n\r\n<p>She waits until theyâ€™re back down to ice cubes before she whispers, â€œThanks.â€ He just shrugs and gives his mouth a quick upturn at the corners. â€œDo you want to get out of here?â€ She asks. â€œMy place is close by. I have an apartment. I mean, I live alone there. No oneâ€™s there now.â€ He just stares at her. She starts to giggle again, and then leans her head back and laughs so that her neck stretches out like the wing of a pidgeon. He thinks it looks too long and too breakable. She composes herself and looks nervously around the room at the other customers. He canâ€™t think of anything better to do so he stands up and says, â€œOK.â€</p>\r\n'),(2557,'Clawing my way back to life, I still have a few remnants of my recent bout with my viral adversary. Well, to be honest the final blows are still being thrown but in the interest of positive thinking I am declaring victory a little early. For some odd reason this particular viral adversary had some strange abilities beyond that of its contemporaries that have taught me to respect it, as one does a worthy opponent.<br><br>\r\nFirst off, it was a full body infection that lead me to believe at one point that it had destroyed my bodies ability to deal with the build up of lactic acids in my muscles. I would think of the tin man rusting in the Wizard of Oz as I lay in bed trying to make my limbs move.<br><br>\r\nThe next symptom impacted my genital organs. I awoke one morning to the unpleasant sensation that a surgeon had opened up my scrotum, carefully extracted each of my testicles and replaced them with a quantity of molten lead, then stiched everything back together.<br><br>\r\nThe third abnormal tactic in the biological war between myself and the virus was the inflamation of my right nipple. Having pierced both nipples approximately a year and a half ago I was taken off guard when the right one seemingly out of no where had suddenly swollen and started to excrete a pasty yellow ooze. I couldn\\\'t help wondering what this ooze consisted of alas I have no means of finding out really.<br><br>\r\nSo on the first day of spring I was busy in the final battle against my worthy adversary. I had little time to contemplate all the other ways in which my life is being rejuvinated this spring. A quick reflection lists off a new job to be started in April, a new romantic interest, new friends moving into town, and hopefully new clean bill of health.<br><br>\r\nHappy Spring Swinney.org'),(2559,'<p>\r\nwhere the fuck is he?\r\n</p>\r\n<p>\r\nthe day started great. i was in my bed. lying there. i stared at the flashing light on his tv for a few hours no doubt about that. its just keeps going. green. nothing. green. nothing. green. nothing. it just does that. forever. \r\n</p>\r\n<p>\r\nhe woke up. atlast!\r\n</p>\r\n<P>\r\nman he does a lot of shit when he wakes up. i just dont know which way to scamper. \"fuckit, ill camp midstaircase.\" \r\n</p>\r\n<p>\r\nthe sink scares me. he\'s shaving. midstaircase licking my ass. he is shaving. he is up. he will be upstairs soon. life is good. \r\n</p>\r\n<p>\r\njust as i had figured, he\'s coming upstairs. he\'s yanking at my tail again. does he wanna play? is he mad? whatthefuckisgoingonohmygod!!! god i hate it when he does that. \r\n</p>\r\n<p>\r\nmental note(is this possible)/bite the fuck out of his forearm next time he does that. fucker. \r\n</P>\r\n<p>\r\nfollowing him down the hall i become a bit sidetracked by the vase with the euktaliptus(catscantsspell), i shake a few toys off, whacking them around the tile. i like attacking really little things. well only if they are non-living. im scared of ants. i only play with things about as bit as one claw...not living. im such a pussy. har har. \r\n</p>\r\n<P>\r\nbored. where is he. downstairs. i got the fuck down there fast. he is at the desk. jump. he shoves me down. jump. down. jump. down. jump. sucsess!!! \r\n</p>\r\n<P>\r\nmental note. bite him if he doesn\'t let me stay on second jump. \r\n</p>\r\n<p>\r\nfor the love of garfield he\'s going upstairs again. run. run. run. fuck the vase. he\'s outside. the forbidden zone. will he be back? where the fuck is he. \r\n</p>\r\n<p>\r\nrecon at the front north eastern window provides uptodate intelligence on the going\'s on of my best friend. fire sticks again. bright. right. brighter. red. brighter. red. what the fuck does that kind of colour smell like? forbidden zone sucks. i wanna go there so bad. \r\n</p>\r\n<p>\r\nhe\'s back. yay. ok focus. cant get tangled in curtains. yes. sucsess. \r\n</p>\r\n<p>\r\nkitchen. sniff food. mmmmmmmmmmmmmmmmmmmm seafood smell.\r\n</p>\r\n<p>\r\nhe\'s talking to old lady....moving around quickly. he\'s out the door. forbidden zone. \r\n</p>\r\n<p>\r\nn/e window. he\'s getting into a moving shiny box. bird. box. kid across the street. box. box gone. bird. kid across the street. where the fuck is he?\r\n</p>\r\n<p>\r\nhmmmmmm, im going to go sniff the old lady in the kitchen. she talks to me when no one is home. but when anyone is home she doesnt act nice to me. she is wierd like that. \r\n</p>'),(2560,'<img src=\"http://swinney.org/journals/images/2560_1.gif\" height=\"300\" align=\"center\"><br><br>\r\nWith the help of a handful of dedicated fishermen, I was born back in 1899. Today, I have grown more than my founding fishermen could have ever dreamed. Were I a corporation, I\'d employemploys over 5,000 hard working men and women, and be an international company selling canned tuna and salmon throughout the world under the label \"Poonlarp Quality Meats\" and in Canada and Australia under the \"Mack Diggety\" brand name.<br><br>\r\n\r\nI would have canning facilities in Mayaguez, Puerto Rico; Manta, Ecuador; and Santa Fe Springs, Ca. Over the years, Poonlarp-MackDiggety Products, Inc. would transform its plants from labor intensive production lines to machine automated lines. I would keep up with today\'s technology, this is fairly certain. This would make my corporate conglomerate able to provide a quality product at a competitive price. When consumers see the \"Poon\" on a canned seafood product, they could be assured it would mean <i>quality</i>. <br><br>\r\nQuality, however, would not be all the Poon-MackDiggetyÂ® (PMd) brand name would stand for. PMdÂ® would also stand for variety. Our famous \"PoonMack\" would be found on a variety of premium quality seafood products. The PoonMack is on canned crab meat, shrimp, oysters, clams and of course every PMdÂ® Seafood best seller, particularly the piquantly seasoned albacore and salmon. PMdÂ® would be a full service seafood provider!<br><br>Families all across America would grow up on the delicious taste of PMd Seafoods. They\'d enjoy it in sandwiches, salads, casseroles, even right out of the can, this I <i>guarantee</i>.\r\n'),(2561,'<p>the other night i finished working late. usually i sit in front of the muted tv in my living room, reading and rereading my notes until my eyes start to wander. infomercials and christian evangelist shows come on channel 4 and it\\\'s time to go to bed. </p>\r\n\r\n<p>for whatever reason i had a lot of shit to carry upstairs; books, music, violet\\\'s cage and a pile of mail. so somewhere in between the third and fourth step (somewhere in between the third and fourth verses of the song) my hot-pink fuzzy easy spirit slippers failed me and i bit it. hard. everything went flying, including the cage, and i landed on my left knee as if in some ice dance gone awry.</p>\r\n\r\n<p>i\\\'ve been in my house alone for a week now, and overall it\\\'s been blissfully quiet and lovely. i can smoke in the bathtub, blast sigur ros in the morning; i can sit in my kitchen in my underwear and drink hot lemon tea. the presence of my six housemates doesn\\\'t really keep me from doing this sort of thing, but i\\\'m admittedly less bashful about it when i know there\\\'s noone around. the pace of things changes, you know, i\\\'m not tracking to anyone but myself. so it\\\'s been rejuvenating, i\\\'ve been content.</p>\r\n\r\n<p>sitting there on the stairs that night, though, trying to comfort my petrified rodent pet, i felt horrid and pathetic and alone. my knee fucking hurt and there was no one to rub it except the dustbunnies that live on our stairs. so i rocked back and forth, telling violet that i was sorry i dropped her on her ass, and cried hot tearless cries. </p>'),(2562,'<p>For the last few days I\\\'ve been in Chaing Rai, just south of the borders of Burma and Laos in the golden triangle. Once known for an extremely lucrative opium trade, there arenâ€™t any poppy fields to be seen these days. Not on the Thai side of the border anyway, or at least not near any of the roads I\\\'ve been on. (And I\\\'ve been on some pretty deserted back roads lately). What there is to see are tea farms, and endless rice terraces, rising up the hillsides into the clouds.</p>\r\n\r\n<p>We stopped by The House of Opium, a nice little museum filled with very old pipes and other paraphernalia. There are post cards and books on growing opium poppies. The man at the desk opened a jar and said, â€œYou want some opium!?â€ and tilted the contents toward me. Dried fruits. He laughs at his joke for the 15th time that day and tells me that it isnâ€™t really opium. Aside from the museum, all you get to see in the golden triangle are hilltribe crafts for sale at high prices. We got much better deals on the crap we bought west of Chaing Mai. So all we buy in Chaing Rai are salty plums and dried fruit and cans of coke.</p>\r\n\r\n<p>Luckily when youâ€™re riding a motorcycle, you donâ€™t need to buy any crafts at the tourist traps anyway, you can wait and load up on them for less money in the hilltribes themselves... We are back in the land of \\\"HELLO!\\\" here. You can have an entire conversation with a hilltribe villager saying only the word \\\"hello\\\" and using various different intonations. I crack up every time an old hilltribe villager stops and screams \\\"HELLO!\\\"  at the passing motorcycle. One woman walking up the middle of the road stopped dead in her tracks, a look of fear rising in her eyes when she saw the bike, and then suddenly, a flash of recognition! She smiled, waited until we were almost upon her, then threw up one arm and screamed â€œHELLO!â€ She just about scared the crap out of me.</p>\r\n\r\n<p>We went and visited some more caves outside of town. We went to a really huge one and showed up just as some other strange westerners got there. One guy who lived around there with his little Thai wife. We all wandered in at the same time and 6 of us walked deep into the cavern. There were no lights, no tour guides, just 6 of us with 4 flashlights among us fumbling along in the dark. I stopped when the next cavern was only reachable by squirming along flat to the ground, but it was scarier to wait alone in the small chamber with only a fading borrowed flashlight and the drip drip drip of the stalactites. The cave was completely alive with the sound of water. A young cave. Most of the others I\\\'ve seen arenâ€™t so full of such recent formations.</p>\r\n\r\n<p>Later I went back to the guesthouse to play guitar with the old weird drunk South African dude who wouldnâ€™t shut up about \\\"jamming\\\" with me. Of course itâ€™s the same every time, when I do sit down to play he gets distracted by his next drink or Grease2 playing on the satellite TV. So I have to sit and play alone to the sounds of the skinny white Irishman getting an unsanitary Thai style tattoo out in the courtyard. It seems that in the off-season there are fewer 20 yr old tourists and many more weird old men tourists... I think they must be here for the 2 week Thai girlfriend experience. But I tell you some of them are too weird to even land any of the industrious Thai women.\r\n</p>'),(2563,'<p>bored at work and infatuated with list posts, i cleaned out the top right drawer of my desk today. here is what i found:</p> \r\n* three dove dark chocolate eggs. mmmm.<br>\r\n* birthday card from the time i turned 26. on front: 70s daisies, hottie in striped dress, the words â€˜â€˜you go girl!â€™â€™<br>\r\n* invitation from birthday party last year in santa ynez wine country. pretty purple. â€˜â€˜come taste the wine.â€™â€™<br>\r\n* random piece of notebook paper with mysterious phone number in mysterious handwriting: 917-7112.<br> \r\n* tube of hot pink lip gloss<br>\r\n* friends\\\' wedding invitation from last summer. mike and vanessa began a lifetime of togetherness. i hear they\\\'re breaking up.<br>\r\n* weird hand-written letter from prison inmate asking me to help him correct an injustice he claims was done against him by his parole officer. includes pictures of his children.<br>\r\n* 13 old paycheck stubs. yep. all that money\\\'s gone now.<br> \r\n* three credit cards i was clearly trying to hide from myself.<br>\r\n* â€˜â€˜application to rent or leaseâ€™â€™ from casa marina apartments from housing search last summer. (found a much better place!)<br> \r\n* two plastic spoons to use for snacking: yogurt, oatmeal, spicy chinese soup, what have you.<br>\r\n* not one, not two, but three pairs of sunglasses<br>\r\n* magazine article i wrote about <a href=\\\"http://www.gvsite.com/\\\">goran visnjic</a> oooooh yeah.<br>\r\n* travel packet of advil<br>\r\n* one silver hoop earring. (yay! i found it!)<br>\r\n'),(2564,'<P>\nsamui, thailand.\n</P><P>\nthe care taker of the buildings we are staying at rented egg and i a\ndirt bike, 220 cc.  some sort of generic yamaha thing.  he told us\nthere was a great scenic viewpoint that very few tourists go to, and\nencouraged us to go there. he also gave egg a number of words of\ncaution in thai language.  she loosely translated them to \"watch out\non the turns.\"\n</P><P>\nwe struck out on our journey and had some trouble finding anything in\nthe way of a dirt road that was headed towards  a mountain.  we found\nsomething that looked like it was going in the right direction and\neventually saw some signs that said \"View Point -->\"  and followed\nthose.  paths often met and crossed.  we joked about taking the one\nless traveled.  we also made viet nam jokes whenever we thought the\nterrain was getting rough.  \"man, now this is the shit,\" we said over\nand over again.  and the shit got worse and worse.  at points, the\nbike could not go up with both of us on it with the front tire still\non the ground.  wheelies were popped.  sweat was dripping.  we were\nMTV extreme.  we were the travel channel, extreme.  if we had packed a\nlunch, we would have been extreme chef\'s on the cooking channel off to\neat curry and larb on the side of the fucking shit in tropical\nthailand.\n</P><P>\nat point, the shit was single track.  at point, the shit was looking\nworse than a bombed out and strafed makeshift supply road through to\nsome remote supply base behind enemy lines.  at times, it looked like\nthe concrete that was occasionally showing up and totally destroyed,\nwas air dropped in from an F16.  it was gnarly.  i referred to it as a\nhuman grater, a flesh eater.  i was scared and i was driving.  egg was\na trooper.  she never balked.  she never screamed.  she never said,\n\"You fucking asshole!  What have you gotten us into?!\"\n</P><P>\nabout three quarters of the way leg one of our trip, egg had to start\nwalking because it was too steep to have both of us on.  the bike was\nsmall and i could not reach the back brake without applying it.  when\nthe shit sloped down hill,   she had to get off so i could use the\nback brake to stabilize.  at one point after a wrong turn up a\nseriously heinous incline up a loose and rocky stretch, she got off\nand we both stared down.  this was the first time on the trip that i\nhad to turn back.  both of us knew i would not make it.  \"Swinney is\ngoing for the gold,\" i said.  i took a few more deep breaths.  i\nstarted down knowing i was a goner. the bike hit a rock and i hit the\nthrottle by accident.  the bike was gone and i was doing a shoulder\nrole off the path.  \"sweet,\" i said dusting myself off, and gave the\nhang loose.  from there on out, when i had to take the shit on a down\nhill, i walked the bike.  by shit in this case, i mean the broken\nconcrete human grater.\n</P><P>\nwe eventually found the vista, but the sky was darkening and we were\nin a panic.  how would we make it back before dark?  egg walked most\nof the way back down and i idled the bike while riding the back and\nfront brake simultaneously.  i parked the bike at one point, crashed\non my adrenaline rush and disappointed in myself, feeling like a\nfailure, and staring at an decline of grater that was analogous on a\ndeep personal level to Jaws.  i thought of Jaws chewing me up,\nstarting with whatever part hit the ground first.  could be a\nshoulder, could be a hand, could be an elbow, but THE REST would\nfollow directly.    egg caught up to me.  \"i cant do it.  this is\ninsanity.  i\'ll pay your friend whatever money he wants to come get\nthis bike.\"  then i walked it down the 40 feet of two track grater.\nat the bottom, the road became smooth.  egg got on the back and we\nended up taking a more traveled road back, one of the possible routes\nup that we missed in the first place.  it was smooth from there on\nout.\n</P><P>\nwhen i got back to the bungalow, i showered and had dinner with egg,\neve and jim.  then completely exhausted, retired.  egg tried to give me\na massage but i kept falling asleep and waking up only  to scream\nmercy and fall back into a dream.\n</P><P>\ntoday i am sore.  i would like to do some more super extreme MTV\nbiking another time, but that was enough for this trip.\n</P><P>'),(2565,'what a silly thing to do</br>\r\nnow it looks like a lemon</br>\r\na bad copy of a taxicab</br>\r\nwhy did you paint it yellow?<p>\r\nyou said it\\\'d make you feel better</br>\r\nand do away with bad feelings</br>\r\na sort of color therapy</br>\r\nstill it looks so awkward<p>\r\nstupid duckie yellow</br>\r\nthis is getting serious</br>\r\npeople tell me that you\\\'re mad</br>\r\nwas it not enough, dear<p>\r\nwith the yellow hats and yellow shirts</br>\r\nthe yellow shoes and yellow skirts</br>\r\nand yellow hair and yellow eyes</br>\r\nand that silly song called yellow<p>\r\nand your maniac smile\r\n</br>\r\nwith yellow teeth</br>\r\nmakes me want to add blue\r\n</br>\r\nto make them green\r\n'),(2566,'<P>something comes to me<BR>in the rarest of moments:<BR>everything\\\'s alright.<BR><BR>(i cheat at haiku:<BR>i know that \\\"everything\\\'s\\\"<BR>has four syllables,<BR><BR>but, really, come now<BR>surely we can bend the rules<BR>just a little bit.)<BR><BR>time moves in spirals<BR>didn\\\'t we just have easter?<BR>(seems that way, i know.)<BR><BR>i\\\'m going to stop<BR>wasting all my precious time.<BR>save my money, too.<BR><BR>oh, yeah, promises.<BR>i know you\\\'ve heard it before:<BR>spring resolutions.<BR><BR>i don\\\'t need absinthe,<BR>cokehashbeerpotcrackjunk or<BR>aguardiente.<BR><BR>can i have good times<BR>with just me on my lonesome?<BR>no drugs or liquor?<BR><BR>you bet your sweet ass.<BR>i like my own company<BR>just fine, thank you much.<BR><BR>in three weeks, i\\\'ll be<BR>in new york city, baby.<BR>cleared it with peter.<BR><BR>all you tri-state girls<BR>get ready; i\\\'ll be there soon.<BR>we\\\'ll have a parade:<BR><BR>all you honeys from<BR>darien, connecticut,<BR>daddy\\\'s little girls:<BR><BR>papa knows my name.<BR>have him take you to the bank,<BR>\\\'cause i don\\\'t come cheap.<BR><BR>all you downtown girls,<BR>black-wearing hipster mamas:<BR>i\\\'ll change your mindset.<BR><BR>you\\\'ll be wearing white<BR>from easter til labor day<BR>once you\\\'ve had ol\\\' matt.<BR><BR>all you uptown girls:<BR>billy joel can write songs<BR>out the ass for you,<BR><BR>but you ain\\\'t heard shit<BR>til you hear the songs you\\\'ll sing<BR>when i come around.<BR><BR>you bellevue girls on<BR>the edison medicine:<BR>tell your nurses, too.<BR><BR>have \\\'em change the sheets<BR>and postpone the therapy<BR>and basket-weaving.<BR><BR>you harlem women:<BR>i know that there are some things<BR>your men will not do,<BR><BR>but i swear to you<BR>i\\\'m the tongue-wielding jesus.<BR>come get you some, girl.<BR><BR>staten island girls:<BR>who lives in staten island?<BR>look into moving.<BR><BR>while i\\\'m there, i want<BR>to go to columbia<BR>and read a screenplay.<BR><BR>an unproduced one.<BR>it\\\'s in the rare books section<BR>of their library.<BR><BR>i\\\'d also like to<BR>try to get an appointment<BR>with joseph steiglitz.<BR><BR>more and more, i think<BR>i\\\'d like to write for money:<BR>freelance travel stuff.<BR><BR>they say words are cheap,<BR>mostly propping up nothing.<BR>signifying what?<BR><BR>did you people know<BR>that any damn thing at all<BR>can be poetry?</P>'),(2567,'Ã¿Ã˜Ã¿Ã \Z%&\'()*456789:CDEFGHIJSTUVWXYZcdefghijstuvwxyzÆ’â€žâ€¦â€ â€¡Ë†â€°Å â€™â€œâ€â€¢â€“â€”Ëœâ„¢Å¡Â¢Â£Â¤Â¥Â¦Â§Â¨Â©ÂªÂ²Â³Â´ÂµÂ¶Â·Â¸Â¹ÂºÃ‚ÃƒÃ„Ã…Ã†Ã‡ÃˆÃ‰ÃŠÃ’Ã“Ã”Ã•Ã–Ã—Ã˜Ã™ÃšÃ¡Ã¢Ã£Ã¤Ã¥Ã¦Ã§Ã¨Ã©ÃªÃ±Ã²Ã³Ã´ÃµÃ¶Ã·Ã¸Ã¹Ãº$4Ã¡%Ã±\Z&\'()*56789:CDEFGHIJSTUVWXYZcdefghijstuvwxyzâ€šÆ’â€žâ€¦â€ â€¡Ë†â€°Å â€™â€œâ€â€¢â€“â€”Ëœâ„¢Å¡Â¢Â£Â¤Â¥Â¦Â§Â¨Â©ÂªÂ²Â³Â´ÂµÂ¶Â·Â¸Â¹ÂºÃ‚ÃƒÃ„Ã…Ã†Ã‡ÃˆÃ‰ÃŠÃ’Ã“Ã”Ã•Ã–Ã—Ã˜Ã™ÃšÃ¢Ã£Ã¤Ã¥Ã¦Ã§Ã¨Ã©ÃªÃ²Ã³Ã´ÃµÃ¶Ã·Ã¸Ã¹ÃºÃ¿Ã€8Â â€OjNVvÂ¸Ã¯+\\&Â¸Æ’nÃ¥Â³Ë†?R?Ã’Å¸ËœÂ®ÃŠÃ­sÃº$_Ã·ÃŠÃ¿Ã±Ã¾Ã€sD5CnÃ€Ã¾Ã­AÃ¬jyÂ¢=FË†!lâ€¢â€°*+Â Ã”Fâ€šÃ¿Ã Æ’ÃšÅ¡â€˜!&Ã±ÂµV2N{VÃ‰Â¢lNÂªÃƒË†Jâ€”Q!Ã²Ãœâ€¢\'Ã²mÂ»Â±Ã˜VÂ´Â«+Ã™â€œ(hTâ€ a4Ã²>07dQYÃšz+AÃ’ÃŽÃ¬Ã˜,HÃ´Â¬?Y=Ã˜Ã¹RÅ¾3Ãšâ€”3Ã®U?BÃ€NBÃ±?ZÃŠÂ²DÂ¨\\R0Â§9Â¬UYniÃˆâ€ Å’gÂ Â©u[\"`ÃˆA$.3â‚¬khÃ”Ã“S7E;ÃÃ¼MKÂ©Ã˜|Â£Â PC\'Ã“Å½Ã•|Ã‰Â¢lJÂ¨ÃÃ¤Ã»Ã’Ã§Â°Ã¬RÂº?fÂºË†0Â·Ã–â€¦=Ã…â€ 4Ã¹@Â¨Â¾Â£+Eq&Ã¾Qâ‚¬Ã¾Ã·Â¡Kâ€”Â¨Ãš\',Â²nd#â€˜â€šGjÃT[â„¢Â´1Â¢[Ë†dB@â€ Ã¿Ã£KÃ˜Ãµ)TVÂ±F7Ã£ÃŒVÃ·&Â³pIÃ¨ÃŠRÃ²%kwdÃŒNÂµJ?ÃµÂ¸?AÂ¶Ã¨Ã‰\rÃƒ5ÃWIXÃ’:Â«â€™Ã–E\n:Pâ€“Ã‚Ã®Ã¾Ã©ÃiOr$Yâ€™ eÃ¹â€ >â€šÂ¶v3\"â€˜DÂ£Ã²sâ€šÂ«ÃšÂ¡ËœÃ½?<Å½Â¤Ã•Â¨â€°Â²;y)Ã¶Ëœâ€˜Ã“â€ywÃ®Z.Ã€Ã³Å â€¡Q?DGâ€˜?nÃªZÂ¸ÃŒN%kUÃq<Ã‘Â¶7r*â€ºÂ³BÃ€Ã³3â€ \'>Ã•<ÃžAaÃ«Â¸g&â€¦ Â±]38Ãµ94JÃ¶\Z%Ã²Ã”?â€˜Ã´Â¨hw!xÃÃ²2Â¦*^Â¥-\nÃ‰â€˜r	Ã©Ã«U`â€“Ã…ÃÃ€Â¯<SiË†Å“Ã¼Å“ÃµÃ´Â¡,Â¢â€™â‚¬Æ’VÃ®Hâ€¡Å¾ÃÃ¶Â©Ã¦Å â€“ÃŒÃ¦yâ€“FÃŽÃ–Ã‚?nÂ¿Ã–Â¯Â 2Ã”Å’dÃ¶Â¤Ã´â„¢OÃŠ2IÃ¬F1PÃâ€ Âµ*4MÂªÃŠICÃºU^Ã¨kÃâ€ U?zÃ§\'Ã¨FÅ¾kzoS7Â±â€¹?JÃ˜â€˜9Ã‹BÂ®lÃ 0?â€¦\ZÃ‡*Â°Ã´Â£AÃœÂ±Â»=qZBÃ†rFÃ²>Ã¦#ojvl?â€ Â´9`JÃ»QÃˆ$RÂ¡\\Å¾zU+ZÃŒZâ€ž.?M/bO?â€¢ZÃÂ¥?(#Â¡Ã…KÅ“V?ÃŠÃ„i@Ã¬E