INSERT INTO `comments` VALUES (8,136,'2000-11-11 17:17:47',0,'jesse','i still say scam, but hell yeah, see where it goes!  the most disgusting thing about the current state of the election is that the masses are acting like a mob instead of intelligent, informed peeps.  i hate that GW won the election, but for chrissakes, let it go people.  don\'t do this frickin protest crap.  it\'ll even out...uh, or something',6,0,0,0,NULL,'en'),(7,137,'2000-11-11 17:10:31',0,'jesse','rad, rad, rad.',5,0,0,0,NULL,'en'),(309,294,'2001-05-04 19:41:22',0,'robotec9','i think it would be great if i\r\nreached a point where i became\r\na powerful force simply in\r\nbeing who i am.  that i could\r\nno longer concieve of myself\r\nas a human with boundries. \r\n...you know, like neo.',0,0,0,0,NULL,'en'),(5,137,'2002-03-05 01:46:04',17,'austin','you can use this new commentator for commentary posts like this one above.  =-)',2,0,0,0,NULL,'en'),(9,145,'2000-11-12 01:52:09',0,'wacko','dope',1,0,0,0,NULL,'en'),(10,147,'2002-03-05 01:46:04',17,'austin','hmmm, that sounds about right.  \r\nI haven\'t had psychedelics in years\r\nor a ....  you know.',2,0,0,0,NULL,'en'),(11,146,'2002-03-05 01:46:04',17,'austin','post some of those emails, yeo! what do you mean walk all over you?  ',3,0,0,0,NULL,'en'),(12,148,'2000-11-13 03:05:55',0,'your name','no html for now please',2,0,0,0,NULL,'en'),(13,148,'2000-11-13 03:41:08',0,'bmg','Damn DUDE!!! I wanna go eat Thai food in Frisco... I\'d also like to go hang out with Sean!',5,0,0,0,NULL,'en'),(14,146,'2000-11-13 11:03:51',0,'BMG','I will post emails on my site, soon nuff. I mean \"walk all over me\" in the sense that I am not about to support two...',1,0,0,0,NULL,'en'),(15,146,'2000-11-13 15:52:54',0,'Mr. Miaygi','snort salt danielsan!  snort salt!',4,0,0,0,NULL,'en'),(16,148,'2000-11-13 18:01:30',0,'Lonna','HI, Austin!!',2,0,0,0,NULL,'en'),(17,135,'2000-11-13 18:10:33',0,'LGC','\"won\", not \"one\":)',3,0,0,0,NULL,'en'),(18,148,'2002-03-05 01:46:04',1