INSERT INTO `multi_info` VALUES (1,124,'SouthEast Asia','<P>Testing. this is a bunch of posts about thailand.  this is a bunch of posts about thailand.this is a bunch of posts about thailand.this is a bunch of posts about thailand.this is a bunch of posts about thailand.</P>'),(24,187,'China walks toward me','tiny round trip from dream to life'),(5,187,'Freeway','Man, Machine, Toll Booth, and Cops.'),(6,124,'Rubber Band',NULL),(26,337,'hello applecore.',NULL),(13,123,'The Crash','a crash in what appears to be a south western desert.'),(14,82,'Dance Magazine',NULL),(15,59,'I Am [Ethnicity]','Celebrate your ethnicity here! Did you spend your childhood in a foreign country? Do you have stories of strange foods foisted upon you by well-meaning relatives from \"the old country\"? Or perhaps you have a tidbit or etymology to share. Swinney.org wants to know!'),(18,187,'the happy complainer','you don\'t need to be <i>that</i> organized to be negative. or do you?<br>\r\ni\'m not sure by now if the articles in this series will gather anything else than my negative thoughts. too much organization may end up in giving something positive out of it, right?'),(27,17,'Pets','<P>We love our pets.  Wayne Bremser thinks pet owning is a form of slavery.  i like to think of it as co-existance if it is a cat, co-dependence if it is a dog.  either way, some pet are really great.  others are evil.  perhaps that is where the owner reflection part of pets comes in.</P>\r\n\r\n<P>this series is dedicated to pets.</P>'),(25,295,'',NULL),(16,65,'dreams','</b>swinney articles about dreams. if you have an article about a dream, email me and i\'ll add it to this series. i am elly@elly.org. thanks.'),(17,196,'i - ching',NULL),(19,156,'an arranged marriage','making sense of something that is foreign to me, but that i was brought up for.'),(20,175,'b',NULL),(23,75,'wasted',NULL),(22,175,'a',NULL),(28,90,'The Days Wear On:',NULL),(29,17,'Tracking The Yeti','Mythical creatures of the woods, with special powers.  Chronicles of pursuit.  Encounters.  Profiling.  Dried tracks in the mud.'),(30,17,'No Title At This Time','Still very abstract, much too much for an Abstract.'),(31,17,'Letters From New York City',NULL),(32,17,'2961','wserterw'),(33,251,'Manny Swindle','a disturbed young man'),(34,307,'vessel',NULL),(35,371,'Karekare',NULL),(36,371,'Lyrics',NULL),(37,66,'World Trade Center','<i>no source of power is adequate, no fleet of shiny flaming planes, no diabolical stabs of hate, no monsoon of shattered half-mirrored glass raining down on Wall Street can encroach on God\'s fated kinematics...</i>'),(38,124,'',NULL),(39,124,'Standing Up (What comes after Rubber Band)',NULL),(40,410,'Citizen 2Y0844\\\'s Junior Year Abroad','Journal: Alien Story\r\nideas for posting strategy:\r\ngive it a title that is repeated with each dispatch such as:<br>\r\n\"Adventures of Citizen y00408\"<br>\r\n\"Citizen y00408\'s Junior Year Abroad\"<br>\r\nadd a link to the very first story so people get background if they want it<br>\r\nmake each post a long one = a short, short story\r\n\r\n<br>\r\nalien character:<br>\r\nsends dispatches to home planet<br>\r\ntakes form of female<br>\r\nCan see things that humans can\'t see, like<br>\r\nthe portals to other planets in emtpy/broken elevators and out of order bathroom stalls (bathroom stalls take it home, broken elevators take it into the past, the amount of time depending on the time debt that people in that building have spent in the elevator, so sky-scrapers are best for traveling back long amounts of time.)<br>\r\nNY is convenient for it, because there are lots of tall buildings and broken bathroom stalls.<br>\r\nthe \"inner children\" of people acting out the emotions of the adult in public (shadow-orphan, ego-proxy, ego-orphan)<br>\r\nNot everyone has ego-orphans that are so clear, some are shadowy<br>'),(41,176,'',NULL),(42,175,'Taxi Stories',NULL),(43,420,'',NULL),(44,420,'',NULL),(45,420,'',NULL),(46,65,'classic \'comments\' argumentia','sometimes the comments section gets out of control. this series is a retrospective of the times that has happened. email me if you have contributions to this series.'),(47,124,'Tendencies',NULL),(48,66,'Roberto','Real-life ramblings about my apartment\'s superintendent.'),(49,66,'The Infidels:',NULL),(50,17,'Motorcycle Madness','Tales of motorcycing, or involving motorcycles.  The Sacred Three A\'s: Adventure, Action, Ass-whipping.  You will find them all here in their full glory.'),(51,251,'',NULL),(52,251,'The Breakup',NULL),(53,251,'Chrissy','Chris - Christine - Punk'),(54,66,'Boot Camp:',NULL),(55,187,'techniques de survie pour ressembler Ã  un humain',NULL),(56,187,'(delete this one)',NULL),(57,66,'Los Angeles',NULL),(58,66,'People:',NULL),(60,175,'Food: Bonding and Identity','le: \"all things are food, passing through us...\" \r\n<br>\r\n<br>\r\negg: \"food is such a loaded subject, so dear and so indicative of cultural and relational dynamics\"\r\n<br>\r\n<br>\r\nsimon: \"cooking was the easiest way to get around the real details\"'),(61,17,'Tears In My Beer','Tales of longing, lefting, and lurking after the one you loved, hated, cannot live without.'),(62,273,'Jeremy Kittledown',NULL),(63,195,'out and about in the world',NULL),(64,175,'Objects: Totem, Currency, Fetish and Relic','Who are we?  To what do we aspire?  We collect things; we arrange things in space.  We employ symbols: sublime; seductive; trite.  Through objects we are known - or concealed.'),(65,66,'',NULL),(66,66,'Lovebytes 2004',NULL),(67,82,'',NULL),(68,82,'Dream Notes',NULL),(69,66,'Transcience',NULL),(70,66,'Ikea:',NULL),(71,122,'photo public','things i think about shooting photos in the streets of toronto'),(72,175,'',NULL),(73,175,'Cult of Swinney',NULL),(74,175,'Our Wars',NULL),(75,175,'Family & Childhood: Roots',NULL),(76,231,'horrible affliction week',NULL),(77,587,'Just keep scribbling, I guess',NULL),(78,66,'Eleven Eleven','The Doorway of the 11:11 opens once and closes once and only One may pass through... The Doorway of the 11:11 opened on January 11, 1992 and is now scheduled to close on November 11, 2011. 11:11 is a pre-encoded trigger \r\nplaced into our cellular memory banks prior to our descent into matter. The 11:11 is hereby being activated...\r\n'),(79,175,'Eros: Love, Sex and Loss in Short Form','The comic, tragic, romantic and absurd movements of the heart - in the briefest articles.'),(80,618,'',NULL),(81,618,'Trainwreck',NULL),(82,17,'Christmas With The Swinnies','Put on your footie pajamas, curl up by that yule log, load up the egg nog, grab a slice of that disgusting joojoobee cake shit, switch to the TIVOed stop motion Rudolf the Reindeer, and hit the bong hard.  <I>It is Christmas.</I>'),(83,604,'mr. murray','the continuing story of a bear'),(84,175,'The Meaning of Life','austin: \"sunday whether i like it or not is always my day of heavy understanding.\"'),(85,675,'corporate samurai',NULL),(86,682,'Guilty Pleasures',NULL),(87,17,'Wolfen (2005)','A city in terror, a man torn between going to work everyday and eating humans at night, struggles to come to terms with his disease, AND his love for, nay -- <i>lust</i> -- for a woman.'),(88,93,'christmas eve',NULL),(89,839,'Butterflies',NULL),(90,195,'invisible planet',NULL);
