INSERT INTO `shorts` VALUES (1,'austin','at work after hours</P><P></P><P>after turning over all the beverage packet dispencers looking for hot chocolate</P><P></P><P>two days later in a cold apartment</P><P></P><P>with cold footed slippers</P><P></P><P>out of the back pocket comes three bags of peppermint tea</P><P></P><P>no! throw them into the fire!</P><P></P><P>but a cup of tea would be good right now.</P><P></P><P>no! tossed the tea because there was no hot chocolate.  finish the job.</P><P></P><P>after hours when the house sleeps</P><P></P><P>sneaking into the trash</P><P></P><P>a hot cup of tea will not jeprodize the arguement '),(2,'austin','<P>\r\nsitting in yeti\\\'s desk\r\n</P>\r\n<P>\r\ndreaming of harbin hot pool\r\n</P><P>\r\nspaced out hippy poems\r\n</P> '),(3,'egg','sunday. im listening for the elevator, and eating sugar. maybe i will drive to the country with amazons. maybe you will come over. '),(4,'austin','eating cheese\r\n<BR><BR>\r\nwanting things'),(5,'austin','<P>\r\ni dont love driving that drive\r\n</P><P>\r\nsometimes if traffic is moving\r\nfast i can day dream most of the way\r\n</P><P>\r\nbut i would love to just live\r\nacross the street from egg\r\n</P><P>\r\nand not work\r\n</P>'),(6,'austin','she was out at the nickelodian movie\r\n<BR><BR>\r\nwithout me!\r\n<BR><BR>\r\ni want her to run away with me.\r\n<BR><BR>\r\nshe is suggesting places:\r\n<BR><BR>\r\na barn by the sea\r\n<BR><BR> \r\ngrad school in texas\r\n<BR><BR>\r\nshe doesnt know how hot it is there\r\n<BR><BR>\r\nyou can only make art at night'),(7,'egg','how about<br>\r\na barn on a boat<br>\r\nwith big windows<br>\r\nthat we can drive between texas and boston and california and asia and egypt and scotland and norway?<br>\r\nthe light would go in one side<br>\r\nacross my bunk bed<br>\r\nand then through the other window to hit the water'),(8,'egg','it\\\'s wednesday<br>\r\nand i get to sleep with austin swinney tonight.'),(9,'austin','i saw this book, physics for game developers.  exploding particles.  racecars banking.  rockets lifting off.  these things make me happy.'),(10,'egg','i had dinner with a friend who just got back from India. He explained what was wrong with America: too much scheduling, too much rushing, noone wants to hang out. He asked if he should sleep over and I told him I had too much stuff to do.'),(11,'austin','<P>im up really late \r\nworking on the site.  i have\r\nto pee real bad, but the office\r\nis dark and i am scared to go\r\nto the bathroom.  i should\r\nreally go home.  i should get\r\nsome sleep.  i did so much stuff\r\ntoday i cant slow down.</P>'),(12,'egg','I have been abducted, I have been seducted and reducted and deducted from the rational ocean and carried to the shore with my asspants stuck to my behind and sticky pieces of summertime hair stuck to my face.'),(13,'austin',''),(14,'austin','oh there is so many things for single men to do out there!  i work all week and when saturday night comes i go partying in the city and the girls love me and life is so great!!!\r\n<BR><BR><BR>\r\nit is really cold in bed at night when she is on the other side of the planet.  it is emotional distance that is the coldest.'),(15,'austin','<P>\r\nann is gone<BR>\r\nher desk is still warm<BR>\r\ni check her work into cvs<BR>\r\nall the rings are now aligned!</P>'),(16,'ix','kielbasa sausage, your butt cheeks is warm.'),(17,'william blake','<PRE>\r\nEvery night and every morn\r\nSome to misery are born.\r\nEvery morn and every night\r\nSome are born to sweet delight.\r\nSome are born to sweet delight,\r\nSome are born to endless night.\r\n</PRE>'),(18,'egg',''),(19,'egg','did you see the full moon? it was our 9th full moon. the luckiest number in thailand is 9, because the thai word for 9, <i>gaow</i> is phonetically the same as the term <i>gaow-NA</i> which means \\\"to move forward\\\": '),(20,'austin','thinking of <BR>\r\ncoming up with<BR>\r\nsome conclusion to <BR>\r\nthe question that <BR>\r\nkeeps popping up <BR>\r\nevery day <BR>\r\nmore than once<BR>\r\nusually of <BR>\r\nto what end <BR>\r\ni should spend <BR>\r\nthis time <BR>\r\nwhich passes <BR>\r\nwhether i want it to <BR>\r\nor not.<BR>'),(21,'austin','twenty bucks says this does not work.\r\n'),(22,'egg','this still works.'),(23,'omfg','php intervention');
