INSERT INTO `thoughts` VALUES (3,'2002-09-16 21:36:16',17,'austin','i just found a button to piss off my friend.',0,NULL,'en'),(2,'2002-09-16 21:36:16',17,'austin','me too!',0,NULL,'en'),(1,'2002-09-16 21:36:16',17,'austin','weezer kicks ass.',0,NULL,'en'),(4,'2002-09-16 21:36:16',17,'austin','i just found a button to piss off my friend.',0,NULL,'en'),(5,'2002-09-16 21:36:16',17,'austin','new wu-tang is fun.',0,NULL,'en'),(6,'2000-11-21 03:37:57',0,'bmg','o0O(what is this?)',0,NULL,'en'),(7,'2000-11-21 15:04:29',0,'efgtr','tgt4g',0,NULL,'en'),(8,'2002-09-16 21:36:16',17,'austin','it is morning, i am the first person at work, how much longer can this go on?',0,NULL,'en'),(9,'2002-09-16 21:36:16',17,'austin','santa?  Santa Claus?  Please bring me a BitchX connection for christmas.',0,NULL,'en'),(10,'2000-11-21 17:53:43',0,'bmg','LA here i come...',0,NULL,'en'),(11,'2002-09-16 21:36:16',17,'austin','tylenol cold medicine in the day time, i\\\'m a drab high.  i want to ooze out of my chair and fall asleep under my cubicle cage.',0,NULL,'en'),(12,'2000-11-21 20:34:38',0,'puppy','mmmmmm. sugar and caffine.... ',0,NULL,'en'),(13,'2000-11-21 20:34:49',0,'name','thought',0,NULL,'en'),(14,'2000-11-21 20:40:26',0,'leonard','why must people continue to vandalize my ride? ',0,NULL,'en'),(15,'2000-11-21 21:38:50',0,'adamajah','A.D.A.M.: Android Designed for Assassination and Mathematics',0,NULL,'en'),(16,'2002-09-16 21:36:16',17,'austin','i could use a laptop to curl up with at home and go to sleep.  sick, huh?',0,NULL,'en'),(17,'2002-09-16 21:36:16',17,'austin','what kind of company makes you work on the friday between thanksgiving (thurs.) and the weekend?  sheesh.',0,NULL,'en'),(18,'2000-11-22 19:24:29',0,'leonard','they bought you and they sold you and they made you for their pleasure.',0,NULL,'en'),(19,'2002-09-16 21:36:16',17,'austin','arnie, get off the phone!',0,NULL,'en'),(20,'2002-09-16 21:36:16',17,'austin','i\\\'m HUNGRY',0,NULL,'en'),(21,'2000-11-24 02:40:24',0,'prin